// Banco de preguntas tipo examen de residencia (Colombia). Cada pregunta: área, tema, dificultad (1-3), enunciado, opciones, índice correcto, explicación y perla.
window.BANCO = [
// ================= CARDIOLOGÍA =================
{id:"c01",area:"Cardiología",tema:"SCA",dif:2,q:"Hombre de 58 años, hipertenso y fumador, con dolor torácico opresivo de 2 horas, diaforesis y náuseas. ECG: elevación del ST de 3 mm en DII, DIII y aVF con descenso en DI y aVL. ¿Cuál es la arteria más probablemente ocluida?",o:["Descendente anterior","Coronaria derecha","Circunfleja","Tronco de la coronaria izquierda"],a:1,e:"La elevación del ST en derivaciones inferiores (DII, DIII, aVF) corresponde a infarto inferior, cuya arteria culpable es la coronaria derecha en ~80 % de los casos (circunfleja en el resto). La descendente anterior produce elevación en V1-V4 (anterior) y el tronco da descenso difuso del ST con elevación en aVR.",p:"ST elevado en DIII > DII + descenso en DI/aVL favorece coronaria derecha; pida siempre V3R-V4R para buscar compromiso del ventrículo derecho."},
{id:"c02",area:"Cardiología",tema:"SCA",dif:2,q:"Paciente con IAM inferior, hipotensión (80/50), ingurgitación yugular y pulmones limpios. ¿Cuál es la conducta inicial más apropiada?",o:["Nitroglicerina sublingual","Furosemida IV","Bolo de cristaloides","Morfina IV"],a:2,e:"La tríada hipotensión + yugulares ingurgitadas + pulmones limpios en IAM inferior indica infarto del ventrículo derecho. El VD es precarga-dependiente: el manejo inicial es volumen. Nitratos, morfina y diuréticos reducen la precarga y pueden precipitar colapso.",p:"En infarto de VD: volumen sí, nitratos no."},
{id:"c03",area:"Cardiología",tema:"Falla cardíaca",dif:2,q:"Mujer de 64 años con falla cardíaca con FEVI 30 %, clase funcional NYHA II, ya recibe enalapril, carvedilol y espironolactona a dosis óptimas, con K 4.2 y TFG 60. ¿Qué fármaco agregar para reducir mortalidad?",o:["Digoxina","Dapagliflozina","Amlodipino","Ivabradina"],a:1,e:"Los inhibidores de SGLT2 (dapagliflozina, empagliflozina) reducen mortalidad cardiovascular y hospitalización en falla con FEVI reducida independientemente de diabetes, y son uno de los cuatro pilares junto con ARNI/IECA, betabloqueador y antagonista mineralocorticoide. La digoxina reduce hospitalizaciones pero no mortalidad; la ivabradina se reserva para FC ≥70 en ritmo sinusal pese a betabloqueador; el amlodipino es neutro.",p:"Los 4 pilares de la FEVI reducida: ARNI (o IECA/ARA), betabloqueador, ARM e iSGLT2."},
{id:"c04",area:"Cardiología",tema:"Fibrilación auricular",dif:2,q:"Mujer de 72 años, hipertensa y diabética, con fibrilación auricular de reciente diagnóstico, asintomática, FC 88. ¿Cuál es el puntaje CHA2DS2-VASc y la conducta respecto a anticoagulación?",o:["2 puntos; anticoagular solo si hay síntomas","4 puntos; anticoagular con ACOD","3 puntos; aspirina","4 puntos; anticoagular solo si hay cardioversión"],a:1,e:"Edad 65-74 (1) + sexo femenino (1) + HTA (1) + DM (1) = 4 puntos. Con ≥2 en mujeres (≥1 en hombres sin contar sexo) se recomienda anticoagulación oral, preferiblemente con anticoagulantes directos (ACOD) salvo estenosis mitral moderada-severa o válvula mecánica. La aspirina no es alternativa para prevención de ictus en FA.",p:"CHA2DS2-VASc: C falla, H hipertensión, A2 edad ≥75, D diabetes, S2 ictus/AIT previo, V vascular, A edad 65-74, Sc sexo femenino."},
{id:"c05",area:"Cardiología",tema:"Hipertensión",dif:2,q:"Hombre de 45 años con PA 160/100 pese a enalapril, amlodipino e hidroclorotiazida a dosis máximas. Potasio 3.0 mEq/L, bicarbonato 31. ¿Cuál es el diagnóstico más probable?",o:["Feocromocitoma","Hiperaldosteronismo primario","Estenosis de arteria renal","Síndrome de Cushing"],a:1,e:"Hipertensión resistente + hipokalemia + alcalosis metabólica es la presentación clásica del hiperaldosteronismo primario, la causa endocrina más frecuente de HTA secundaria. Se tamiza con relación aldosterona/actividad de renina plasmática. El feocromocitoma cursa con crisis paroxísticas; la estenosis renal con deterioro renal tras IECA.",p:"HTA resistente = ≥3 fármacos a dosis óptimas incluyendo un diurético; siempre descarte causa secundaria y mala adherencia."},
{id:"c06",area:"Cardiología",tema:"Endocarditis",dif:2,q:"Hombre de 35 años, usuario de drogas intravenosas, con fiebre de 10 días, soplo nuevo de insuficiencia tricuspídea y nódulos pulmonares múltiples en la radiografía. ¿Cuál es el microorganismo más probable?",o:["Streptococcus viridans","Staphylococcus aureus","Enterococcus faecalis","Candida albicans"],a:1,e:"En endocarditis de válvula tricúspide en usuarios de drogas IV el agente más frecuente es Staphylococcus aureus (incluido SARM). Los émbolos sépticos pulmonares explican los nódulos. S. viridans predomina en válvulas nativas izquierdas tras procedimientos dentales; Candida es rara aunque posible en este grupo.",p:"Endocarditis derecha en UDIV = S. aureus hasta que se demuestre lo contrario; cubra con vancomicina si hay riesgo de SARM."},
{id:"c07",area:"Cardiología",tema:"Arritmias",dif:2,q:"Paciente de 28 años con palpitaciones de inicio súbito; ECG muestra taquicardia regular de QRS estrecho a 180 lpm sin ondas P visibles, estable hemodinámicamente. Las maniobras vagales fallan. ¿Cuál es el siguiente paso?",o:["Amiodarona IV","Adenosina 6 mg IV en bolo rápido","Cardioversión eléctrica sincronizada","Verapamilo oral"],a:1,e:"Taquicardia supraventricular paroxística estable: tras fallar maniobras vagales, la adenosina en bolo rápido (6 mg, luego 12 mg) es el tratamiento de elección por su vida media de segundos. La cardioversión se reserva para inestabilidad. La amiodarona no es primera línea en TSV estable.",p:"Adenosina en bolo rápido seguida de 20 mL de solución salina, por vena proximal; advierta al paciente la sensación transitoria de opresión."},
{id:"c08",area:"Cardiología",tema:"Valvulopatías",dif:3,q:"Hombre de 70 años con síncope de esfuerzo, soplo sistólico rudo en foco aórtico irradiado a carótidas y pulso parvus et tardus. ¿Cuál es el hallazgo ecocardiográfico que define estenosis aórtica severa?",o:["Área valvular <1.5 cm²","Gradiente medio ≥40 mmHg o velocidad pico ≥4 m/s","Gradiente medio ≥20 mmHg","Fracción de eyección <50 %"],a:1,e:"La estenosis aórtica severa se define por área valvular <1.0 cm², gradiente medio ≥40 mmHg o velocidad máxima ≥4 m/s. Síncope, angina o disnea en estenosis severa son indicación de reemplazo valvular (quirúrgico o TAVI). Un área <1.5 cm² es moderada.",p:"La tríada de la estenosis aórtica: angina, síncope, disnea; una vez sintomática, la supervivencia sin cirugía cae a 2-3 años."},
{id:"c09",area:"Cardiología",tema:"Pericardio",dif:2,q:"Mujer de 30 años con dolor torácico pleurítico que mejora al inclinarse hacia adelante, frote pericárdico y elevación difusa del ST con descenso del PR. ¿Cuál es el tratamiento de primera línea?",o:["Prednisona","AINE + colchicina","Anticoagulación","Antibiótico de amplio espectro"],a:1,e:"Pericarditis aguda: la primera línea es un AINE (ibuprofeno o aspirina) más colchicina, que reduce recurrencias. Los corticoides aumentan las recurrencias y se reservan para contraindicación a AINE o causas autoinmunes. La anticoagulación está relativamente contraindicada por riesgo de hemopericardio.",p:"Elevación difusa del ST cóncava + descenso del PR = pericarditis, no infarto."},
{id:"c10",area:"Cardiología",tema:"Tromboembolismo",dif:2,q:"Paciente con dolor torácico pleurítico súbito, taquicardia, saturación 90 %, dímero D elevado y angioTAC con émbolo en rama lobar derecha. PA 120/80, troponina positiva y VD dilatado en eco. ¿Cuál es la conducta?",o:["Trombólisis sistémica inmediata","Anticoagulación y monitoreo (riesgo intermedio-alto)","Filtro de vena cava","Solo oxígeno y observación"],a:1,e:"TEP con PA normal pero disfunción del VD y biomarcadores positivos = riesgo intermedio-alto: anticoagular (HBPM o HNF) y vigilar estrechamente; la trombólisis de rescate se indica solo si hay deterioro hemodinámico. La trombólisis sistémica inmediata se reserva para TEP de alto riesgo (choque o hipotensión sostenida).",p:"Trombólisis en TEP solo con inestabilidad hemodinámica; en riesgo intermedio, anticoagule y observe."},
{id:"c11",area:"Cardiología",tema:"Síncope",dif:1,q:"Mujer de 22 años con síncope tras estar de pie en una fila bajo el sol, precedido de náuseas, sudoración y visión borrosa, con recuperación rápida. Examen físico y ECG normales. ¿Cuál es el diagnóstico más probable?",o:["Síncope cardiogénico","Síncope vasovagal","Crisis epiléptica","Hipoglucemia"],a:1,e:"Pródromos autonómicos, desencadenante típico (bipedestación prolongada, calor) y recuperación rápida sin confusión definen el síncope reflejo vasovagal, el más frecuente en jóvenes. No requiere más estudios si el ECG es normal. El síncope cardiogénico suele ser sin pródromos o de esfuerzo.",p:"Síncope de esfuerzo o sin pródromos en joven: piense cardiopatía estructural (miocardiopatía hipertrófica) y pida ecocardiograma."},
{id:"c12",area:"Cardiología",tema:"Dislipidemia",dif:2,q:"Hombre de 55 años con infarto previo; LDL actual 110 mg/dL con atorvastatina 80 mg. ¿Cuál es la meta de LDL y el siguiente paso?",o:["Meta <100; mantener igual","Meta <55 (o <70); agregar ezetimibe","Meta <130; suspender estatina","Meta <70; cambiar a fibrato"],a:1,e:"En prevención secundaria (muy alto riesgo) la meta es LDL <55 mg/dL (ESC) o al menos <70 con reducción ≥50 %. Si con estatina de alta intensidad no se logra, se agrega ezetimibe y luego un inhibidor de PCSK9. Los fibratos no reducen eventos en este escenario.",p:"Primero estatina de alta intensidad, luego ezetimibe, luego iPCSK9."},
// ================= NEUMOLOGÍA =================
{id:"n01",area:"Neumología",tema:"EPOC",dif:2,q:"Hombre de 68 años, fumador de 40 paquetes/año, con disnea mMRC 2 y 2 exacerbaciones el último año que requirieron corticoide oral. Espirometría: VEF1/CVF 0.60, VEF1 45 %. Eosinófilos 350/µL. ¿Cuál es el tratamiento inhalado de mantenimiento más apropiado?",o:["SABA a demanda","LAMA solo","LAMA + LABA + corticoide inhalado","Corticoide inhalado solo"],a:2,e:"Paciente GOLD grupo E (≥2 exacerbaciones moderadas o 1 hospitalización) con eosinófilos ≥300: la triple terapia (LAMA+LABA+CI) reduce exacerbaciones y mortalidad. El CI en monoterapia no se recomienda en EPOC. LAMA solo sería para grupo A/B sin eosinofilia.",p:"Eosinófilos ≥300 en EPOC exacerbador = agregue corticoide inhalado; <100 = evítelo."},
{id:"n02",area:"Neumología",tema:"Neumonía",dif:2,q:"Mujer de 75 años con neumonía adquirida en comunidad: confusión, urea 15 mg/dL, FR 32, PA 85/55. ¿Cuál es el CURB-65 y la conducta?",o:["2; manejo ambulatorio","3; hospitalizar en piso","4; considerar UCI","1; antibiótico oral"],a:2,e:"CURB-65: Confusión (1), Urea >19 mg/dL (0 aquí), FR ≥30 (1), PA <90/60 (1), edad ≥65 (1) = 4 puntos. Con ≥3 la mortalidad supera el 15 % y se debe hospitalizar evaluando UCI. El manejo ambulatorio se reserva para 0-1; 2 puntos: hospitalización corta u observación.",p:"CURB-65 ≥3 → hospitalizar y evaluar UCI; agregue cobertura para atípicos (macrólido) al betalactámico."},
{id:"n03",area:"Neumología",tema:"Asma",dif:2,q:"Joven de 19 años con crisis asmática: habla en palabras, FR 32, saturación 90 %, PEF 45 % del predicho. Recibió salbutamol nebulizado x3 sin mejoría. ¿Cuál es el siguiente paso?",o:["Aminofilina IV","Bromuro de ipratropio nebulizado + corticoide sistémico + sulfato de magnesio IV","Intubación inmediata","Antibiótico IV"],a:1,e:"Crisis asmática severa sin respuesta a SABA: agregar ipratropio, corticoide sistémico temprano y sulfato de magnesio IV (2 g). La aminofilina no aporta beneficio y tiene toxicidad. La intubación se reserva para falla respiratoria inminente (somnolencia, PaCO2 normal o alta, silencio auscultatorio).",p:"Un paciente asmático con PaCO2 'normal' en crisis severa está agotándose: es signo de alarma."},
{id:"n04",area:"Neumología",tema:"Derrame pleural",dif:2,q:"Derrame pleural con proteínas pleurales/séricas 0.6, LDH pleural/sérica 0.7, glucosa 35 mg/dL, pH 7.1 y predominio de neutrófilos en paciente con neumonía. ¿Cuál es la conducta?",o:["Observación con antibiótico","Toracostomía cerrada (tubo de tórax)","Toracocentesis evacuadora única","Diuréticos"],a:1,e:"Es un exudado (criterios de Light) con pH <7.2 y glucosa <60: derrame paraneumónico complicado/empiema, que requiere drenaje con tubo de tórax además del antibiótico. Los diuréticos solo sirven en trasudados por falla cardíaca.",p:"Criterios de Light para exudado: proteínas >0.5, LDH >0.6 o LDH pleural >2/3 del límite superior sérico."},
{id:"n05",area:"Neumología",tema:"Tuberculosis",dif:2,q:"Paciente con tos de 4 semanas, baciloscopia positiva y VIH negativo. Inicia tratamiento. ¿Cuál es el esquema estándar en Colombia para tuberculosis pulmonar sensible?",o:["2 meses HRZE + 4 meses HR","6 meses HRZE","2 meses HR + 4 meses HRZE","9 meses de isoniazida"],a:0,e:"El esquema acortado es fase intensiva de 2 meses con isoniazida, rifampicina, pirazinamida y etambutol (HRZE) seguida de fase de continuación de 4 meses con HR, en tratamiento directamente observado. Nueve meses de isoniazida es tratamiento de infección latente, no de enfermedad activa.",p:"Efectos adversos clave: isoniazida neuropatía (dar piridoxina), etambutol neuritis óptica, rifampicina orina naranja e inducción enzimática, pirazinamida hiperuricemia."},
{id:"n06",area:"Neumología",tema:"SDRA",dif:3,q:"Paciente en ventilación mecánica por SDRA severo (PaO2/FiO2 90). ¿Cuál es la estrategia ventilatoria con beneficio demostrado en mortalidad?",o:["Volumen corriente 10-12 mL/kg","Volumen corriente 6 mL/kg de peso predicho y presión plateau <30 cmH2O","PEEP de 0 cmH2O","FiO2 100 % permanente"],a:1,e:"La ventilación protectora (Vt 6 mL/kg de peso predicho, presión meseta <30) reduce mortalidad (ARDSNet). En SDRA severo también se recomienda posición prona ≥16 h/día. Volúmenes altos inducen volutrauma.",p:"Peso PREDICHO (según talla y sexo), no peso real, para calcular el volumen corriente."},
{id:"n07",area:"Neumología",tema:"Nódulo pulmonar",dif:2,q:"Hombre de 60 años, fumador, con nódulo pulmonar solitario de 12 mm de bordes espiculados en TAC. ¿Cuál es la conducta más apropiada?",o:["Control con TAC en 2 años","Antibiótico y control en 6 semanas","PET-TC y/o biopsia","Ninguna, es benigno"],a:2,e:"Nódulo >8 mm con características de alto riesgo (espiculado, fumador, >50 años) tiene probabilidad de malignidad alta: se indica PET-TC y biopsia o resección. La vigilancia con TAC seriada se reserva para nódulos pequeños (<8 mm) de bajo riesgo.",p:"Calcificación central, laminar o en palomitas de maíz sugiere benignidad; espiculación y crecimiento sugieren malignidad."},
{id:"n08",area:"Neumología",tema:"Apnea del sueño",dif:1,q:"Hombre obeso de 50 años con ronquido intenso, somnolencia diurna (Epworth 16) y HTA de difícil control. ¿Cuál es el estudio diagnóstico de elección?",o:["Espirometría","Polisomnografía","Gasometría arterial","Ecocardiograma"],a:1,e:"El estándar diagnóstico de la apnea obstructiva del sueño es la polisomnografía (o poligrafía respiratoria domiciliaria en alta probabilidad pretest). El tratamiento de elección en AOS moderada-severa es CPAP.",p:"La AOS es causa reversible de HTA resistente, FA recurrente e hipertensión pulmonar."},
// ================= NEFROLOGÍA / LÍQUIDOS =================
{id:"r01",area:"Nefrología",tema:"Hiponatremia",dif:2,q:"Mujer de 70 años con carcinoma pulmonar de células pequeñas, Na 118 mEq/L, euvolémica, osmolaridad urinaria 450 mOsm/kg, Na urinario 60. Confusa y con cefalea intensa. ¿Cuál es la conducta inicial?",o:["Restricción hídrica","Solución salina al 3 % en bolo","Solución salina al 0.9 % a 150 mL/h","Furosemida"],a:1,e:"Hiponatremia severa sintomática (confusión, cefalea) requiere salina hipertónica al 3 % en bolos de 100-150 mL para subir 4-6 mEq/L en las primeras horas, independientemente de la causa (aquí SIADH). La restricción hídrica es el manejo del SIADH crónico asintomático. La salina 0.9 % puede empeorar la natremia en SIADH.",p:"No corrija más de 8-10 mEq/L en 24 h: riesgo de mielinólisis pontina."},
{id:"r02",area:"Nefrología",tema:"Hiperkalemia",dif:2,q:"Paciente con ERC, K 7.2 mEq/L y ECG con ondas T picudas y QRS ancho. ¿Cuál es la primera medida?",o:["Gluconato de calcio IV","Insulina + dextrosa","Resina de intercambio","Hemodiálisis"],a:0,e:"Ante hiperkalemia con cambios electrocardiográficos la prioridad es estabilizar la membrana miocárdica con gluconato o cloruro de calcio IV (efecto en minutos). Luego se redistribuye el potasio (insulina+glucosa, salbutamol) y finalmente se elimina (diuréticos, resinas, diálisis).",p:"Secuencia: estabilizar (calcio) → redistribuir (insulina, β2) → eliminar (diálisis). El calcio NO baja el potasio."},
{id:"r03",area:"Nefrología",tema:"Ácido-base",dif:2,q:"Gases arteriales: pH 7.20, PaCO2 25, HCO3 10, Na 140, Cl 100. Glucosa 450. ¿Cuál es el trastorno?",o:["Acidosis metabólica con anión gap normal","Acidosis metabólica con anión gap elevado","Acidosis respiratoria","Alcalosis metabólica"],a:1,e:"pH bajo con HCO3 bajo = acidosis metabólica. Anión gap = Na − (Cl + HCO3) = 140 − 110 = 30 (elevado). Compensación esperada (Winter): PaCO2 = 1.5×10 + 8 = 23 ± 2 → adecuada. Contexto de hiperglucemia sugiere cetoacidosis diabética.",p:"Fórmula de Winter: PaCO2 esperada = 1.5 × HCO3 + 8 (± 2)."},
{id:"r04",area:"Nefrología",tema:"Lesión renal aguda",dif:2,q:"Paciente hipotenso por sangrado con creatinina que subió de 1.0 a 2.0 mg/dL en 48 h. Na urinario 10 mEq/L, FENa 0.5 %, sedimento normal. ¿Cuál es la causa más probable?",o:["Necrosis tubular aguda","Lesión renal prerrenal","Glomerulonefritis","Obstrucción"],a:1,e:"FENa <1 % y Na urinario <20 indican riñón intacto que ahorra sodio en respuesta a hipoperfusión: LRA prerrenal. En necrosis tubular aguda la FENa es >2 % con cilindros granulosos. El tratamiento es restaurar el volumen.",p:"FENa no es útil si el paciente recibió diuréticos: use la fracción excretada de urea (<35 % sugiere prerrenal)."},
{id:"r05",area:"Nefrología",tema:"ERC",dif:2,q:"Paciente diabético con TFG 45 mL/min y albuminuria 400 mg/g pese a losartán a dosis máxima. ¿Qué fármaco añadir para enlentecer la progresión renal?",o:["Amlodipino","Inhibidor de SGLT2","Hidroclorotiazida","Doble bloqueo con enalapril"],a:1,e:"Los iSGLT2 reducen progresión de la enfermedad renal diabética y no diabética con albuminuria (CREDENCE, DAPA-CKD). El doble bloqueo IECA+ARA aumenta hiperkalemia y LRA sin beneficio. Finerenona es otra opción en ERC diabética.",p:"Protección renal en ERC albuminúrica: IECA/ARA + iSGLT2 (± finerenona en DM2)."},
{id:"r06",area:"Nefrología",tema:"Síndrome nefrótico",dif:2,q:"Niño de 4 años con edema generalizado, proteinuria 4 g/día, albúmina 1.8 g/dL e hipercolesterolemia, sin hematuria ni hipertensión. ¿Cuál es la conducta más apropiada?",o:["Biopsia renal inmediata","Prednisona empírica","Ciclofosfamida","Diálisis"],a:1,e:"En niños de 1-10 años con síndrome nefrótico típico la causa más frecuente es enfermedad de cambios mínimos, que responde a corticoides; se inicia prednisona sin biopsia. La biopsia se reserva para corticorresistencia o datos atípicos (hematuria, HTA, hipocomplementemia).",p:"Síndrome nefrótico: proteinuria >3.5 g/día, hipoalbuminemia, edema, hiperlipidemia. Nefrítico: hematuria, HTA, oliguria."},
{id:"r07",area:"Nefrología",tema:"Infección urinaria",dif:1,q:"Mujer de 25 años, no embarazada, con disuria y polaquiuria de 2 días, sin fiebre ni dolor lumbar. ¿Cuál es el manejo más adecuado?",o:["Urocultivo y esperar resultado","Nitrofurantoína 5 días (o fosfomicina dosis única)","Ciprofloxacina 7 días","Ceftriaxona IM"],a:1,e:"Cistitis no complicada: tratamiento empírico corto con nitrofurantoína (5 días) o fosfomicina (dosis única) sin necesidad de urocultivo. Las fluoroquinolonas se reservan por resistencia y efectos adversos. El urocultivo se indica en embarazo, recurrencia, falla o pielonefritis.",p:"En embarazada la bacteriuria asintomática SÍ se trata; en no embarazada, no."},
{id:"r08",area:"Nefrología",tema:"Hipercalcemia",dif:2,q:"Mujer de 60 años con calcio 13.5 mg/dL, poliuria, confusión y PTH suprimida; tiene cáncer de mama. ¿Cuál es el manejo inicial?",o:["Furosemida sola","Hidratación con salina isotónica y bisfosfonato IV","Calcitriol","Restricción de calcio en dieta"],a:1,e:"Hipercalcemia maligna severa: primero hidratación vigorosa con salina 0.9 %, luego ácido zoledrónico IV (efecto en 2-4 días) y calcitonina si se requiere descenso rápido. La furosemida solo tras rehidratar. PTH suprimida orienta a causa no paratiroidea.",p:"Hipercalcemia con PTH alta o inapropiadamente normal = hiperparatiroidismo primario; PTH suprimida = malignidad u otras."},
{id:"r09",area:"Nefrología",tema:"Glomerulonefritis",dif:3,q:"Hombre de 24 años con hematuria macroscópica 2 días después de una faringitis, sin hipotensión ni edema, complemento normal. ¿Cuál es el diagnóstico más probable?",o:["Glomerulonefritis postestreptocócica","Nefropatía por IgA","Síndrome de Alport","Nefritis lúpica"],a:1,e:"Hematuria concomitante (sinfaringítica, 1-3 días) con complemento normal es típica de nefropatía por IgA. La glomerulonefritis postestreptocócica aparece 1-3 SEMANAS después de la infección con C3 bajo.",p:"'Sin-faringítica' = IgA (días); 'post-faringítica' = postestreptocócica (semanas, C3 bajo)."},
// ================= ENDOCRINOLOGÍA =================
{id:"e01",area:"Endocrinología",tema:"Cetoacidosis",dif:2,q:"Paciente con DM1, glucosa 480, pH 7.1, HCO3 8, K 3.2 mEq/L. ¿Cuál es la conducta respecto a la insulina?",o:["Iniciar insulina IV de inmediato","Reponer potasio antes de iniciar insulina","Insulina subcutánea cada 4 h","Bicarbonato IV antes de insulina"],a:1,e:"En CAD con K <3.3 se debe reponer potasio ANTES de la insulina, pues ésta introduce K a la célula y puede causar arritmias fatales. La insulina IV en infusión se inicia cuando K ≥3.3. El bicarbonato solo con pH <6.9.",p:"Resolución de CAD: glucosa <200 + dos de: HCO3 ≥15, pH >7.3, anión gap ≤12. No por desaparición de cetonuria."},
{id:"e02",area:"Endocrinología",tema:"Diabetes tipo 2",dif:2,q:"Hombre de 58 años, obeso, DM2 con HbA1c 8.5 % con metformina y antecedente de infarto. ¿Cuál es el fármaco preferido para agregar?",o:["Glibenclamida","Agonista GLP-1 o iSGLT2 con beneficio cardiovascular","Pioglitazona","Insulina NPH"],a:1,e:"En DM2 con enfermedad cardiovascular establecida se prefieren fármacos con beneficio cardiovascular demostrado (agonistas GLP-1 como liraglutida/semaglutida, o iSGLT2 como empagliflozina), independientemente de la HbA1c. Las sulfonilureas causan hipoglucemia y ganancia de peso.",p:"iSGLT2 si predomina falla cardíaca o ERC; GLP-1 si predomina ateroesclerosis u obesidad."},
{id:"e03",area:"Endocrinología",tema:"Tiroides",dif:2,q:"Mujer de 30 años con palpitaciones, pérdida de peso, bocio difuso, exoftalmos y TSH suprimida con T4 libre alta. ¿Cuál es el diagnóstico y el tratamiento inicial?",o:["Tiroiditis subaguda; AINE","Enfermedad de Graves; metimazol + betabloqueador","Bocio multinodular tóxico; yodo radiactivo","Hipotiroidismo; levotiroxina"],a:1,e:"Exoftalmos (oftalmopatía) es exclusivo de la enfermedad de Graves (autoinmune, anticuerpos anti-receptor de TSH). El tratamiento inicial es metimazol (propiltiouracilo solo en primer trimestre de embarazo) más betabloqueador para síntomas adrenérgicos.",p:"Propiltiouracilo en primer trimestre del embarazo; metimazol en el resto (riesgo de aplasia cutis con metimazol)."},
{id:"e04",area:"Endocrinología",tema:"Suprarrenal",dif:2,q:"Mujer de 40 años con astenia, hiperpigmentación de pliegues, hipotensión, Na 128 y K 5.6. ¿Cuál es el diagnóstico más probable y la prueba confirmatoria?",o:["Síndrome de Cushing; cortisol urinario","Insuficiencia suprarrenal primaria; cortisol basal y prueba de estimulación con ACTH","Hiperaldosteronismo; relación aldosterona/renina","Hipotiroidismo; TSH"],a:1,e:"Hiperpigmentación (exceso de ACTH), hiponatremia e hiperkalemia definen insuficiencia suprarrenal primaria (enfermedad de Addison). Se confirma con cortisol matutino bajo y respuesta inadecuada a cosintropina. En la insuficiencia secundaria no hay hiperpigmentación ni hiperkalemia.",p:"Crisis adrenal: hidrocortisona 100 mg IV + salina; nunca retrase el esteroide esperando resultados."},
{id:"e05",area:"Endocrinología",tema:"Hipoglucemia",dif:1,q:"Paciente diabético en tratamiento con insulina, inconsciente, glucometría 35 mg/dL, sin acceso venoso disponible. ¿Cuál es la conducta inmediata?",o:["Jugo de naranja por vía oral","Glucagón 1 mg IM","Esperar acceso venoso para dextrosa","Insulina para corregir"],a:1,e:"En hipoglucemia severa con paciente inconsciente la vía oral está contraindicada (broncoaspiración). Sin acceso venoso, glucagón 1 mg IM o SC; con acceso, dextrosa al 50 % IV. Luego alimentar y buscar la causa.",p:"Tríada de Whipple: síntomas + glucosa baja + mejoría al corregirla."},
{id:"e06",area:"Endocrinología",tema:"Hipotiroidismo",dif:1,q:"Mujer de 45 años con fatiga, intolerancia al frío, TSH 25 mUI/L y T4 libre baja. ¿Cuál es el tratamiento?",o:["Liotironina","Levotiroxina en ayunas","Metimazol","Observación"],a:1,e:"Hipotiroidismo primario manifiesto: levotiroxina, tomada en ayunas 30-60 minutos antes del desayuno, separada de hierro, calcio y omeprazol. Se controla TSH a las 6-8 semanas.",p:"En adulto mayor o cardiópata inicie con dosis bajas (25-50 µg) y titule lentamente."},
{id:"e07",area:"Endocrinología",tema:"Osteoporosis",dif:2,q:"Mujer de 68 años con fractura vertebral por fragilidad y DMO con T-score −2.8. ¿Cuál es la primera línea farmacológica?",o:["Calcio solo","Bisfosfonato oral (alendronato)","Estrógenos","Calcitonina"],a:1,e:"Osteoporosis con fractura por fragilidad: bisfosfonatos (alendronato, ácido zoledrónico) son primera línea junto con calcio y vitamina D. Denosumab es alternativa si hay ERC o intolerancia; teriparatida en muy alto riesgo.",p:"Fractura por fragilidad = osteoporosis clínica aunque el T-score no sea ≤ −2.5."},
{id:"e08",area:"Endocrinología",tema:"Estado hiperosmolar",dif:2,q:"Hombre de 70 años con DM2, glucosa 900 mg/dL, osmolaridad 340, pH 7.35, cetonas negativas, deshidratado y somnoliento. ¿Cuál es la prioridad?",o:["Insulina en bolo alto","Reposición agresiva de líquidos con salina 0.9 %","Bicarbonato","Manitol"],a:1,e:"Estado hiperglucémico hiperosmolar: déficit de agua de 8-10 L; la prioridad es la reposición de volumen, seguida de insulina en infusión a dosis bajas y reposición de potasio. El descenso brusco de osmolaridad puede causar edema cerebral.",p:"EHH: glucosa >600, osmolaridad >320, sin acidosis significativa; mortalidad mayor que la CAD."},
{id:"e09",area:"Endocrinología",tema:"Hipófisis",dif:2,q:"Mujer de 28 años con amenorrea y galactorrea, prolactina 180 ng/mL, sin embarazo ni medicamentos. RM: adenoma de 7 mm. ¿Cuál es el tratamiento de elección?",o:["Cirugía transesfenoidal","Cabergolina","Radioterapia","Observación"],a:1,e:"Los prolactinomas, incluso macroadenomas, se tratan médicamente con agonistas dopaminérgicos (cabergolina de elección por eficacia y tolerancia). La cirugía se reserva para resistencia o intolerancia.",p:"Antes de diagnosticar prolactinoma descarte embarazo, hipotiroidismo y fármacos (antipsicóticos, metoclopramida)."},
// ================= INFECTOLOGÍA =================
{id:"i01",area:"Infectología",tema:"Sepsis",dif:2,q:"Paciente con neumonía, PA 80/40 tras 30 mL/kg de cristaloides, lactato 4.5 mmol/L. ¿Cuál es el vasopresor de primera línea?",o:["Dopamina","Norepinefrina","Vasopresina","Fenilefrina"],a:1,e:"Choque séptico (hipotensión que requiere vasopresor + lactato >2 tras reanimación): la norepinefrina es el vasopresor de primera línea; vasopresina se agrega como segundo agente. La dopamina tiene más arritmias y mayor mortalidad.",p:"Paquete de la primera hora: hemocultivos, antibiótico, lactato, 30 mL/kg de cristaloide si hipotensión o lactato ≥4, vasopresor para PAM ≥65."},
{id:"i02",area:"Infectología",tema:"VIH",dif:2,q:"Paciente con VIH, CD4 40 células/µL, cefalea subaguda, fiebre y rigidez nucal. LCR: presión de apertura 35 cmH2O, tinta china positiva. ¿Cuál es el tratamiento de inducción?",o:["Fluconazol oral","Anfotericina B + flucitosina","Ceftriaxona + vancomicina","Tuberculostáticos"],a:1,e:"Meningitis criptocócica: inducción con anfotericina B (liposomal preferida) más flucitosina, luego consolidación y mantenimiento con fluconazol. Es esencial el manejo de la hipertensión endocraneana con punciones lumbares evacuadoras.",p:"En criptococosis, retrase el inicio del TAR 4-6 semanas para evitar síndrome de reconstitución inmune."},
{id:"i03",area:"Infectología",tema:"Dengue",dif:2,q:"Paciente con fiebre de 4 días, dolor abdominal intenso, vómito persistente, hematocrito que sube de 40 a 50 % y plaquetas 60.000. ¿Cuál es la clasificación y la conducta?",o:["Dengue sin signos de alarma; manejo en casa","Dengue con signos de alarma; hospitalizar y cristaloides","Dengue grave; transfundir plaquetas","Dengue sin signos de alarma; AINE"],a:1,e:"Dolor abdominal intenso, vómito persistente y aumento del hematocrito con descenso de plaquetas son signos de alarma (fase crítica, días 3-7): hospitalizar e hidratar con cristaloides isotónicos. Los AINE están contraindicados (sangrado). La transfusión de plaquetas no se indica profilácticamente.",p:"Signos de alarma de dengue: dolor abdominal, vómito persistente, acumulación de líquidos, sangrado de mucosas, letargia, hepatomegalia >2 cm, aumento del Hto con caída de plaquetas."},
{id:"i04",area:"Infectología",tema:"Meningitis",dif:2,q:"Adulto de 30 años con fiebre, cefalea, rigidez de nuca y petequias. Sospecha meningitis bacteriana. ¿Cuál es la conducta inmediata?",o:["TAC de cráneo antes de cualquier intervención","Hemocultivos, dexametasona y ceftriaxona + vancomicina empíricos; luego punción lumbar","Esperar resultado del LCR para iniciar antibiótico","Aciclovir empírico"],a:1,e:"La sospecha de meningitis bacteriana exige antibiótico empírico inmediato tras hemocultivos (ceftriaxona + vancomicina; ampicilina si >50 años o inmunosupresión por Listeria), con dexametasona antes o con la primera dosis. La TAC previa a la PL solo si hay focalización, inmunosupresión, papiledema o alteración de conciencia.",p:"Petequias + meningitis = meningococo; profilaxis a contactos con rifampicina o ciprofloxacina."},
{id:"i05",area:"Infectología",tema:"Malaria",dif:2,q:"Paciente procedente del Pacífico colombiano con fiebre, gota gruesa positiva para Plasmodium falciparum, sin criterios de gravedad. ¿Cuál es el tratamiento de primera línea en Colombia?",o:["Cloroquina + primaquina","Artemeter-lumefantrina","Quinina IV","Doxiciclina sola"],a:1,e:"Para P. falciparum no complicado la primera línea es la terapia combinada con artemisininas (artemeter-lumefantrina) más primaquina dosis única como gametocida. La cloroquina + primaquina (14 días) es el esquema para P. vivax. La quinina/artesunato IV es para malaria grave.",p:"Malaria grave: artesunato IV. P. vivax: cloroquina + primaquina 14 días (descartar deficiencia de G6PD)."},
{id:"i06",area:"Infectología",tema:"Celulitis",dif:1,q:"Paciente con celulitis purulenta con absceso de 4 cm en el muslo. ¿Cuál es la conducta principal?",o:["Antibiótico oral solo","Incisión y drenaje","Compresas calientes","Antibiótico IV y observación"],a:1,e:"El tratamiento fundamental del absceso cutáneo es la incisión y el drenaje. El antibiótico (que cubra SARM comunitario: TMP-SMX, doxiciclina o clindamicina) se agrega si hay celulitis extensa, síntomas sistémicos o inmunosupresión.",p:"Celulitis no purulenta: cubra estreptococo (cefalexina). Purulenta: cubra S. aureus/SARM."},
{id:"i07",area:"Infectología",tema:"Leptospirosis",dif:2,q:"Agricultor con fiebre, mialgias en pantorrillas, inyección conjuntival, ictericia y falla renal tras exposición a aguas estancadas. ¿Cuál es el diagnóstico y el tratamiento?",o:["Hepatitis A; soporte","Leptospirosis grave (Weil); penicilina o ceftriaxona IV","Dengue grave; cristaloides","Fiebre tifoidea; ciprofloxacina"],a:1,e:"La tríada ictericia + falla renal + hemorragia con exposición a agua contaminada por orina de roedores es el síndrome de Weil (leptospirosis grave). Tratamiento: penicilina G o ceftriaxona IV; doxiciclina en casos leves.",p:"Inyección conjuntival sin secreción + mialgia de pantorrillas = piense leptospira."},
{id:"i08",area:"Infectología",tema:"Antibióticos",dif:2,q:"¿Cuál de los siguientes antibióticos NO tiene actividad contra Pseudomonas aeruginosa?",o:["Piperacilina-tazobactam","Ceftriaxona","Cefepime","Meropenem"],a:1,e:"La ceftriaxona (cefalosporina de 3.ª generación) no cubre Pseudomonas. Las cefalosporinas antipseudomonas son ceftazidima y cefepime; también piperacilina-tazobactam, carbapenémicos (excepto ertapenem), aztreonam, ciprofloxacina y aminoglucósidos.",p:"Ertapenem NO cubre Pseudomonas ni Acinetobacter; meropenem e imipenem sí."},
{id:"i09",area:"Infectología",tema:"Sífilis",dif:1,q:"Hombre con úlcera genital indolora de base limpia y adenopatía inguinal no dolorosa. VDRL 1:32. ¿Cuál es el tratamiento?",o:["Azitromicina 1 g dosis única","Penicilina benzatínica 2.4 millones UI IM dosis única","Doxiciclina 100 mg x 28 días","Ceftriaxona 250 mg IM"],a:1,e:"Chancro sifilítico (sífilis primaria): penicilina benzatínica 2.4 millones UI IM en dosis única. En sífilis latente tardía o de duración desconocida son 3 dosis semanales. Doxiciclina 14 días solo en alérgicos no embarazadas.",p:"Reacción de Jarisch-Herxheimer: fiebre y malestar en las primeras 24 h tras penicilina; no es alergia."},
{id:"i10",area:"Infectología",tema:"Infección asociada al cuidado",dif:2,q:"Paciente hospitalizado con diarrea acuosa profusa tras 7 días de clindamicina, fiebre y leucocitosis de 22.000. ¿Cuál es el tratamiento de elección?",o:["Metronidazol oral","Vancomicina oral","Loperamida","Ciprofloxacina"],a:1,e:"Infección por Clostridioides difficile: vancomicina oral (o fidaxomicina) es primera línea; metronidazol quedó relegado a casos leves sin acceso a los anteriores. Los antiperistálticos están contraindicados. Leucocitos >15.000 o creatinina >1.5 definen episodio grave.",p:"Suspenda el antibiótico precipitante y los inhibidores de bomba de protones si es posible."},
// ================= GASTRO / HEPATO =================
{id:"g01",area:"Gastroenterología",tema:"Hemorragia digestiva",dif:2,q:"Paciente cirrótico con hematemesis masiva y PA 85/50. Tras reanimación, ¿cuál es el manejo farmacológico inicial antes de la endoscopia?",o:["Omeprazol en bolo","Terlipresina (u octreótido) + ceftriaxona","Propranolol","Vitamina K"],a:1,e:"Hemorragia variceal: vasoactivo (terlipresina u octreótido) desde la sospecha y antibiótico profiláctico (ceftriaxona), que reduce infecciones, resangrado y mortalidad. La endoscopia con ligadura se hace en <12 h. El propranolol es profilaxis, no tratamiento agudo.",p:"Transfundir con umbral restrictivo (Hb <7) en hemorragia variceal: la sobretransfusión aumenta la presión portal."},
{id:"g02",area:"Gastroenterología",tema:"Úlcera péptica",dif:1,q:"Paciente con úlcera duodenal y prueba de ureasa positiva para Helicobacter pylori. ¿Cuál es el tratamiento de erradicación recomendado en zonas de alta resistencia a claritromicina?",o:["Omeprazol solo 8 semanas","Terapia cuádruple con bismuto (IBP + bismuto + tetraciclina + metronidazol) 14 días","Amoxicilina 7 días","Ranitidina + sucralfato"],a:1,e:"En regiones con resistencia a claritromicina >15 % (como Colombia) se recomienda terapia cuádruple con bismuto por 14 días, o terapia concomitante. Se confirma la erradicación con prueba de aliento o antígeno fecal 4 semanas después, sin IBP las 2 semanas previas.",p:"Toda úlcera gástrica debe biopsiarse y controlarse endoscópicamente por riesgo de malignidad; la duodenal no."},
{id:"g03",area:"Gastroenterología",tema:"Pancreatitis",dif:2,q:"Mujer de 45 años con dolor epigástrico irradiado a espalda, lipasa 3 veces el límite superior y ecografía con colelitiasis sin dilatación biliar. Bilirrubina normal. ¿Cuál es el manejo inicial?",o:["CPRE urgente","Hidratación con cristaloides, analgesia y nutrición enteral temprana","Antibiótico profiláctico","Cirugía inmediata"],a:1,e:"Pancreatitis aguda biliar leve: manejo de soporte con líquidos (Ringer lactato), analgesia y alimentación oral/enteral temprana. La CPRE urgente solo si hay colangitis u obstrucción persistente. Los antibióticos profilácticos no se recomiendan. La colecistectomía se hace en la misma hospitalización una vez resuelta.",p:"Dos de tres criterios diagnostican pancreatitis: dolor típico, lipasa/amilasa >3 veces, imagen compatible."},
{id:"g04",area:"Gastroenterología",tema:"Cirrosis",dif:2,q:"Cirrótico con ascitis, fiebre y dolor abdominal. Paracentesis: 500 neutrófilos/mm³. ¿Cuál es el diagnóstico y tratamiento?",o:["Peritonitis secundaria; laparotomía","Peritonitis bacteriana espontánea; cefotaxima/ceftriaxona + albúmina","Tuberculosis peritoneal; tuberculostáticos","Ascitis maligna; paracentesis evacuadora"],a:1,e:"≥250 neutrófilos/mm³ en líquido ascítico diagnostica peritonitis bacteriana espontánea. Tratamiento: cefalosporina de 3.ª generación por 5 días y albúmina (1.5 g/kg día 1 y 1 g/kg día 3) para prevenir síndrome hepatorrenal. Luego profilaxis secundaria con norfloxacina.",p:"Gradiente albúmina sérica-ascítica ≥1.1 g/dL = hipertensión portal."},
{id:"g05",area:"Gastroenterología",tema:"Hepatitis",dif:2,q:"Paciente asintomático con HBsAg positivo, anti-HBc IgG positivo, HBeAg negativo, ADN-VHB 1.500 UI/mL y ALT normal. ¿Cuál es la interpretación?",o:["Hepatitis B aguda","Infección crónica por VHB inactiva (portador inactivo)","Vacunado","Hepatitis B resuelta"],a:1,e:"HBsAg positivo por >6 meses con HBeAg negativo, carga viral baja (<2.000) y transaminasas normales corresponde a infección crónica HBeAg-negativa inactiva: vigilancia cada 6-12 meses, sin tratamiento. El vacunado solo tiene anti-HBs; el resuelto tiene anti-HBs y anti-HBc.",p:"Anti-HBc IgM = infección aguda. Solo anti-HBs = vacuna. Anti-HBs + anti-HBc = infección pasada resuelta."},
{id:"g06",area:"Gastroenterología",tema:"Enfermedad inflamatoria",dif:2,q:"Mujer de 25 años con diarrea sanguinolenta crónica, tenesmo y colonoscopia con inflamación continua desde el recto hasta el colon descendente. ¿Cuál es el diagnóstico más probable?",o:["Enfermedad de Crohn","Colitis ulcerativa","Colitis isquémica","Síndrome de intestino irritable"],a:1,e:"Compromiso continuo desde el recto, limitado a la mucosa y con rectorragia es colitis ulcerativa. Crohn es transmural, parcheado ('lesiones salteadas'), con fístulas y compromiso ileal frecuente, y suele respetar el recto.",p:"Tabaquismo protege en colitis ulcerativa y empeora Crohn; CU se asocia a colangitis esclerosante primaria."},
{id:"g07",area:"Gastroenterología",tema:"Cáncer colorrectal",dif:1,q:"Hombre de 50 años, asintomático, sin antecedentes familiares. ¿Cuál es la estrategia de tamización de cáncer colorrectal recomendada?",o:["No requiere tamización hasta los 60 años","Colonoscopia cada 10 años o sangre oculta en heces anual (inmunoquímica)","Antígeno carcinoembrionario anual","TAC abdominal cada 5 años"],a:1,e:"La tamización se recomienda desde los 45-50 años en riesgo promedio: colonoscopia cada 10 años, prueba inmunoquímica fecal anual o sigmoidoscopia cada 5 años. El ACE no sirve para tamización (solo seguimiento). Con un familiar de primer grado afectado se inicia a los 40 o 10 años antes del caso índice.",p:"Hierro bajo + anemia en hombre o mujer posmenopáusica = colonoscopia hasta demostrar lo contrario."},
{id:"g08",area:"Gastroenterología",tema:"Encefalopatía hepática",dif:1,q:"Cirrótico con somnolencia, asterixis y amonio elevado tras estreñimiento de 4 días. ¿Cuál es el tratamiento de primera línea?",o:["Restricción total de proteínas","Lactulosa hasta 2-3 deposiciones blandas al día","Flumazenil","Diálisis"],a:1,e:"La lactulosa es la primera línea de la encefalopatía hepática; rifaximina se agrega para prevenir recurrencias. La restricción proteica ya no se recomienda porque empeora la sarcopenia. Siempre buscar precipitantes: infección, sangrado, estreñimiento, sedantes, hipokalemia.",p:"Precipitantes de encefalopatía: infección (PBE), hemorragia digestiva, estreñimiento, benzodiacepinas, deshidratación."},
// ================= HEMATOLOGÍA =================
{id:"h01",area:"Hematología",tema:"Anemia",dif:1,q:"Mujer de 32 años con menstruaciones abundantes, Hb 9 g/dL, VCM 70 fL, ferritina 8 ng/mL. ¿Cuál es el diagnóstico y tratamiento?",o:["Talasemia menor; no tratar","Anemia ferropénica; hierro oral","Anemia de enfermedad crónica; eritropoyetina","Anemia megaloblástica; B12"],a:1,e:"Microcitosis con ferritina baja confirma deficiencia de hierro. Tratamiento: sulfato ferroso oral (en días alternos mejora la absorción y tolerancia) durante 3-6 meses tras normalizar la Hb para reponer depósitos. En talasemia menor la ferritina es normal y el RDW es normal.",p:"Ferritina es reactante de fase aguda: puede ser 'normal' en ferropenia + inflamación; use saturación de transferrina."},
{id:"h02",area:"Hematología",tema:"Anemia megaloblástica",dif:2,q:"Hombre de 65 años con anemia macrocítica (VCM 115), parestesias en pies, ataxia y gastritis atrófica. ¿Cuál es la causa más probable?",o:["Deficiencia de folato","Deficiencia de vitamina B12 (anemia perniciosa)","Hipotiroidismo","Alcoholismo"],a:1,e:"Macrocitosis con síntomas neurológicos (degeneración combinada subaguda) y gastritis atrófica autoinmune es anemia perniciosa por deficiencia de B12 (anticuerpos anti-factor intrínseco). La deficiencia de folato no produce neuropatía. Tratar con B12 parenteral.",p:"Nunca dé folato solo ante macrocitosis sin descartar B12: corrige la anemia pero empeora el daño neurológico."},
{id:"h03",area:"Hematología",tema:"Coagulación",dif:2,q:"Paciente anticoagulado con warfarina presenta INR 9 sin sangrado. ¿Cuál es la conducta?",o:["Plasma fresco congelado","Suspender warfarina y dar vitamina K oral a dosis baja","Continuar misma dosis","Concentrado de complejo protrombínico"],a:1,e:"INR >4.5-10 sin sangrado: suspender warfarina y considerar vitamina K oral 1-2.5 mg; INR >10 sin sangrado, vitamina K oral 2.5-5 mg. El complejo protrombínico y la vitamina K IV se reservan para sangrado mayor.",p:"Sangrado mayor con warfarina: complejo protrombínico de 4 factores + vitamina K 10 mg IV."},
{id:"h04",area:"Hematología",tema:"Leucemia",dif:2,q:"Hombre de 60 años asintomático con linfocitosis de 25.000 persistente, linfocitos maduros pequeños y sombras de Gumprecht en el frotis. ¿Cuál es el diagnóstico más probable?",o:["Leucemia linfoide aguda","Leucemia linfocítica crónica","Linfoma de Hodgkin","Mononucleosis infecciosa"],a:1,e:"Linfocitosis absoluta de linfocitos maduros con sombras de Gumprecht en adulto mayor es leucemia linfocítica crónica, confirmada por citometría de flujo (CD5+, CD19+, CD23+). Muchos casos no requieren tratamiento inicial (vigilancia).",p:"LLA = blastos en niño; LMA = blastos con bastones de Auer en adulto; LMC = cromosoma Filadelfia (BCR-ABL)."},
{id:"h05",area:"Hematología",tema:"Trombocitopenia",dif:3,q:"Mujer de 30 años con fiebre, anemia hemolítica con esquistocitos, plaquetas 15.000, creatinina 1.4 y alteración neurológica fluctuante. ¿Cuál es el tratamiento urgente?",o:["Transfusión de plaquetas","Plasmaféresis (recambio plasmático)","Esteroides solos","Heparina"],a:1,e:"Anemia hemolítica microangiopática + trombocitopenia ± síntomas neurológicos = púrpura trombocitopénica trombótica (deficiencia de ADAMTS13). El recambio plasmático es urgente y salva vidas; la transfusión de plaquetas está contraindicada.",p:"Esquistocitos + plaquetas bajas: PTT (neurológico), SHU (renal, niño con diarrea sanguinolenta), CID (coagulación alterada)."},
{id:"h06",area:"Hematología",tema:"Transfusión",dif:2,q:"Paciente recibe transfusión de glóbulos rojos y a los 10 minutos presenta fiebre, dolor lumbar, hipotensión y orina oscura. ¿Cuál es la conducta inmediata?",o:["Disminuir la velocidad de infusión","Suspender la transfusión, mantener acceso venoso con salina y verificar identidad de la unidad","Administrar antihistamínico y continuar","Administrar paracetamol"],a:1,e:"Reacción hemolítica aguda (incompatibilidad ABO): detener de inmediato la transfusión, mantener vía con salina, hidratar para proteger el riñón, enviar la unidad y muestras al banco de sangre. La fiebre sola sin hemólisis sería reacción febril no hemolítica.",p:"Dolor lumbar + orina oscura durante transfusión = hemólisis aguda hasta demostrar lo contrario."},
{id:"h07",area:"Hematología",tema:"Mieloma",dif:2,q:"Hombre de 68 años con dolor óseo, anemia, hipercalcemia, creatinina 2.5 y proteína M en suero. ¿Cuál es el diagnóstico?",o:["Metástasis óseas de próstata","Mieloma múltiple","Hiperparatiroidismo","Linfoma"],a:1,e:"CRAB (hiperCalcemia, falla Renal, Anemia, lesiones óseas (Bone)) con paraproteína monoclonal define mieloma múltiple, confirmado con ≥10 % de células plasmáticas en médula. Las lesiones son líticas 'en sacabocado'.",p:"Mieloma: VSG muy elevada, hiato proteico, lesiones líticas que NO captan en gammagrafía ósea."},
// ================= REUMATOLOGÍA =================
{id:"u01",area:"Reumatología",tema:"Artritis reumatoide",dif:2,q:"Mujer de 40 años con artritis simétrica de pequeñas articulaciones de manos de 3 meses, rigidez matutina >1 h, factor reumatoide y anti-CCP positivos. ¿Cuál es el tratamiento de primera línea?",o:["AINE solos","Metotrexato","Prednisona a largo plazo","Hidroxicloroquina sola"],a:1,e:"El metotrexato es el fármaco modificador de elección al diagnóstico de artritis reumatoide, con ácido fólico para reducir toxicidad. Los corticoides se usan como puente a dosis bajas y corta duración. Los AINE solo alivian síntomas sin modificar la enfermedad.",p:"Anti-CCP: más específico que el factor reumatoide y predictor de erosiones."},
{id:"u02",area:"Reumatología",tema:"Gota",dif:1,q:"Hombre de 50 años con monoartritis aguda del primer dedo del pie, dolorosa, eritematosa, sin fiebre; líquido sinovial con cristales en aguja con birrefringencia negativa. ¿Cuál es el tratamiento de la crisis?",o:["Alopurinol de inmediato","AINE, colchicina o corticoide","Antibiótico IV","Reposo únicamente"],a:1,e:"Crisis de gota: AINE, colchicina (dosis bajas) o corticoides según comorbilidades. El alopurinol no se inicia durante la crisis aguda (si ya lo toma, no se suspende). Cristales de urato: aguja, birrefringencia negativa. Pirofosfato (pseudogota): romboides, positiva.",p:"Siempre puncione una monoartritis aguda para descartar artritis séptica, aunque parezca gota."},
{id:"u03",area:"Reumatología",tema:"Lupus",dif:2,q:"Mujer de 25 años con artralgias, eritema malar, úlceras orales, proteinuria 2 g/día y ANA 1:640 con anti-ADN de doble cadena positivo y C3 bajo. ¿Cuál es el siguiente paso?",o:["Prednisona a dosis bajas y control","Biopsia renal para clasificar nefritis lúpica","Metotrexato","Observación"],a:1,e:"Lupus con proteinuria significativa indica nefritis lúpica; la biopsia renal clasifica el tipo (ISN/RPS) y define el tratamiento de inducción (clase III/IV: ciclofosfamida o micofenolato + corticoide). Todos los pacientes con lupus reciben hidroxicloroquina.",p:"Anti-Sm y anti-dsDNA son específicos de lupus; anti-dsDNA y complemento bajo marcan actividad."},
{id:"u04",area:"Reumatología",tema:"Artritis séptica",dif:2,q:"Paciente de 45 años con fiebre y monoartritis de rodilla. Líquido sinovial: 80.000 leucocitos/mm³ con 90 % de neutrófilos. ¿Cuál es la conducta?",o:["AINE y observación","Drenaje articular + antibiótico IV empírico (cubrir S. aureus)","Corticoide intraarticular","Alopurinol"],a:1,e:">50.000 leucocitos con predominio de PMN es artritis séptica hasta que se demuestre lo contrario: drenaje (artrocentesis repetida o artroscopia) y antibiótico IV empírico tras cultivos (vancomicina ± ceftriaxona). La infiltración de corticoide está contraindicada.",p:"En adulto joven sexualmente activo con poliartralgia migratoria y tenosinovitis piense en gonococo."},
{id:"u05",area:"Reumatología",tema:"Vasculitis",dif:3,q:"Mujer de 72 años con cefalea temporal de reciente inicio, claudicación mandibular, VSG 95 mm/h y pérdida visual transitoria. ¿Cuál es la conducta inmediata?",o:["Biopsia de arteria temporal y luego decidir","Iniciar corticoide a dosis altas de inmediato y programar biopsia","AINE","Aspirina sola"],a:1,e:"Arteritis de células gigantes con síntomas visuales: iniciar prednisona 1 mg/kg (o metilprednisolona IV si hay pérdida visual) de inmediato para evitar ceguera; la biopsia se realiza en los días siguientes y sigue siendo positiva. Se asocia a polimialgia reumática.",p:"Edad >50 + cefalea nueva + VSG alta = arteritis de células gigantes; el esteroide no espera la biopsia."},
// ================= NEUROLOGÍA =================
{id:"l01",area:"Neurología",tema:"ACV",dif:2,q:"Hombre de 65 años con hemiparesia derecha y afasia de inicio hace 2 horas, PA 170/95, glucosa 110, TAC sin hemorragia, NIHSS 14. ¿Cuál es la conducta?",o:["Aspirina 300 mg y observación","Trombólisis IV con alteplasa (o tenecteplasa) y evaluar trombectomía","Reducir la PA a <140/90 antes de cualquier intervención","Anticoagulación con heparina"],a:1,e:"ACV isquémico dentro de las 4.5 h sin contraindicaciones: trombólisis IV; con oclusión de gran vaso (NIHSS alto) también trombectomía mecánica (hasta 6 h, o 24 h con imagen de perfusión). La PA se trata solo si >185/110 antes de trombolizar. La aspirina se difiere 24 h tras trombólisis.",p:"PA permisiva en ACV isquémico sin trombólisis: tratar solo si >220/120."},
{id:"l02",area:"Neurología",tema:"Epilepsia",dif:2,q:"Paciente con crisis tónico-clónica generalizada de 10 minutos que persiste. Ya tiene acceso venoso. ¿Cuál es el fármaco de primera línea?",o:["Fenitoína IV","Lorazepam (o diazepam) IV","Ácido valproico IV","Fenobarbital"],a:1,e:"Estado epiléptico (crisis >5 min): benzodiacepina IV (lorazepam 4 mg, o diazepam; midazolam IM si no hay acceso) como primera línea; si persiste, segunda línea con levetiracetam, valproato o fenitoína. Verificar glucometría y vía aérea.",p:"Primera línea = benzodiacepina; segunda = levetiracetam/valproato/fenitoína; tercera = anestésicos en UCI."},
{id:"l03",area:"Neurología",tema:"Cefalea",dif:2,q:"Mujer de 40 años con 'el peor dolor de cabeza de su vida' de inicio súbito, rigidez de nuca y TAC de cráneo normal a las 8 horas. ¿Cuál es el siguiente paso?",o:["Alta con analgesia","Punción lumbar buscando xantocromía","RM de cráneo en 1 semana","Triptán"],a:1,e:"Cefalea en trueno obliga a descartar hemorragia subaracnoidea. La TAC es muy sensible en las primeras 6 h pero pierde sensibilidad después; si es negativa se realiza punción lumbar buscando xantocromía/eritrocitos. Si se confirma, angiografía para aneurisma.",p:"Nimodipino en HSA previene vasoespasmo; la hidrocefalia y el resangrado son complicaciones tempranas."},
{id:"l04",area:"Neurología",tema:"Guillain-Barré",dif:2,q:"Hombre de 30 años con debilidad ascendente simétrica progresiva 2 semanas después de una gastroenteritis, arreflexia y LCR con proteínas altas sin células. ¿Cuál es el tratamiento?",o:["Corticoides IV","Inmunoglobulina IV o plasmaféresis","Antibiótico","Piridostigmina"],a:1,e:"Síndrome de Guillain-Barré (disociación albúmino-citológica, antecedente de Campylobacter): inmunoglobulina IV o plasmaféresis; los corticoides NO son útiles. Vigilar capacidad vital y disautonomía por riesgo de falla ventilatoria.",p:"Capacidad vital <20 mL/kg o caída rápida = intubación electiva en Guillain-Barré."},
{id:"l05",area:"Neurología",tema:"Parkinson",dif:1,q:"Hombre de 68 años con temblor de reposo unilateral, bradicinesia y rigidez en rueda dentada. ¿Cuál es el tratamiento más eficaz para los síntomas motores?",o:["Levodopa/carbidopa","Haloperidol","Propranolol","Donepezilo"],a:0,e:"La levodopa es el fármaco más eficaz para los síntomas motores del Parkinson. En pacientes jóvenes pueden iniciarse agonistas dopaminérgicos para retrasar discinesias. El haloperidol (antagonista dopaminérgico) empeora el parkinsonismo.",p:"Parkinsonismo simétrico con mala respuesta a levodopa: sospeche parkinsonismo atípico o farmacológico (metoclopramida, antipsicóticos)."},
{id:"l06",area:"Neurología",tema:"Miastenia",dif:2,q:"Mujer de 28 años con ptosis y diplopía fluctuantes que empeoran al final del día, con debilidad al masticar. ¿Cuál es la prueba diagnóstica de mayor especificidad?",o:["Resonancia cerebral","Anticuerpos anti-receptor de acetilcolina","Electroencefalograma","Punción lumbar"],a:1,e:"Miastenia gravis: anticuerpos anti-receptor de acetilcolina (positivos en 85 % de generalizada); si negativos, anti-MuSK. La electromiografía con estimulación repetitiva muestra decremento. Siempre buscar timoma con TAC de tórax.",p:"Crisis miasténica: debilidad respiratoria; evite aminoglucósidos, fluoroquinolonas, betabloqueadores y magnesio."},
{id:"l07",area:"Neurología",tema:"Demencia",dif:2,q:"Hombre de 72 años con deterioro cognitivo progresivo de 2 años, marcha magnética e incontinencia urinaria. ¿Cuál es el diagnóstico más probable?",o:["Enfermedad de Alzheimer","Hidrocefalia de presión normal","Demencia por cuerpos de Lewy","Demencia vascular"],a:1,e:"Tríada de Hakim-Adams (demencia, trastorno de la marcha, incontinencia) con ventriculomegalia en imagen es hidrocefalia de presión normal, una de las demencias potencialmente reversibles (derivación ventrículo-peritoneal).",p:"Demencias reversibles: hidrocefalia normotensiva, hipotiroidismo, déficit de B12, depresión, hematoma subdural."},
// ================= URGENCIAS / TOXICOLOGÍA =================
{id:"x01",area:"Urgencias y toxicología",tema:"Intoxicación",dif:2,q:"Joven ingiere 15 g de acetaminofén hace 6 horas con intención suicida. Está asintomático. ¿Cuál es la conducta?",o:["Observación y alta si asintomático","Niveles de acetaminofén y N-acetilcisteína","Lavado gástrico y alta","Hemodiálisis"],a:1,e:"Dosis tóxica (>150 mg/kg o >7.5 g): medir niveles a las 4 h o más e interpretarlos con el nomograma de Rumack-Matthew; iniciar N-acetilcisteína sin esperar niveles si no estarán disponibles antes de 8 h. La hepatotoxicidad aparece a las 24-72 h, por lo que estar asintomático no tranquiliza.",p:"N-acetilcisteína es más eficaz en las primeras 8 h pero beneficia incluso tardíamente."},
{id:"x02",area:"Urgencias y toxicología",tema:"Organofosforados",dif:2,q:"Agricultor con sialorrea, broncorrea, miosis, bradicardia, fasciculaciones y olor a insecticida. ¿Cuál es el tratamiento?",o:["Naloxona","Atropina a dosis altas repetidas + pralidoxima","Flumazenil","Bicarbonato de sodio"],a:1,e:"Síndrome colinérgico por organofosforados: atropina (dosis dobladas cada 5 min hasta secar secreciones bronquiales; la midriasis no es la meta) más pralidoxima para reactivar la colinesterasa, y descontaminación. Evitar succinilcolina si requiere intubación.",p:"DUMBELS: Diarrea, Urinación, Miosis, Bradicardia/Broncorrea, Emesis, Lagrimeo, Salivación."},
{id:"x03",area:"Urgencias y toxicología",tema:"Anafilaxia",dif:1,q:"Paciente con urticaria generalizada, edema de labios, estridor e hipotensión tras una picadura de abeja. ¿Cuál es el tratamiento de primera línea?",o:["Hidrocortisona IV","Adrenalina 0.5 mg IM en cara lateral del muslo","Difenhidramina IV","Salbutamol inhalado"],a:1,e:"Anafilaxia: adrenalina IM (0.01 mg/kg, máximo 0.5 mg) en el vasto lateral es la única medida que reduce mortalidad; repetir cada 5-15 min si es necesario. Antihistamínicos y corticoides son adyuvantes y no sustituyen la adrenalina.",p:"La adrenalina va INTRAMUSCULAR, no subcutánea ni IV (salvo paro)."},
{id:"x04",area:"Urgencias y toxicología",tema:"Trauma",dif:2,q:"Hombre de 25 años con trauma torácico cerrado, hipotensión, ingurgitación yugular, desviación traqueal y ausencia de ruidos respiratorios en hemitórax derecho. ¿Cuál es la conducta inmediata?",o:["Radiografía de tórax urgente","Descompresión con aguja o toracostomía digital inmediata","Pericardiocentesis","Intubación orotraqueal"],a:1,e:"Neumotórax a tensión es diagnóstico clínico y amenaza inmediata para la vida: descompresión inmediata (aguja en 5.º espacio intercostal línea axilar anterior/media o toracostomía con el dedo), seguida de tubo de tórax. No se espera imagen.",p:"Ingurgitación yugular + hipotensión en trauma: neumotórax a tensión (sin ruidos) o taponamiento cardíaco (ruidos apagados)."},
{id:"x05",area:"Urgencias y toxicología",tema:"Paro cardíaco",dif:1,q:"Paciente en paro cardíaco con ritmo de fibrilación ventricular. Tras la primera desfibrilación y 2 minutos de RCP persiste en FV. ¿Cuál es el siguiente fármaco?",o:["Atropina 1 mg","Adrenalina 1 mg IV","Amiodarona 300 mg","Bicarbonato"],a:1,e:"En ritmos desfibrilables, tras la segunda descarga se administra adrenalina 1 mg IV cada 3-5 min; la amiodarona 300 mg se da después de la tercera descarga si persiste FV/TV sin pulso. La atropina ya no se usa en paro.",p:"RCP de calidad: 100-120 compresiones/min, 5-6 cm de profundidad, minimizar interrupciones."},
{id:"x06",area:"Urgencias y toxicología",tema:"Quemaduras",dif:2,q:"Adulto de 70 kg con quemaduras de segundo grado en el 30 % de la superficie corporal. ¿Cuál es el volumen de Ringer lactato para las primeras 24 h según Parkland?",o:["4.200 mL","8.400 mL","2.100 mL","12.600 mL"],a:1,e:"Parkland: 4 mL × kg × % SCQ = 4 × 70 × 30 = 8.400 mL, la mitad en las primeras 8 h desde la quemadura y el resto en las 16 h siguientes, ajustando a diuresis de 0.5-1 mL/kg/h.",p:"Solo se cuentan quemaduras de 2.º y 3.º grado; vigile diuresis para ajustar."},
// ================= CIRUGÍA =================
{id:"q01",area:"Cirugía",tema:"Abdomen agudo",dif:1,q:"Joven de 20 años con dolor periumbilical que migra a fosa ilíaca derecha, anorexia, fiebre de 38 °C y leucocitosis. Signo de Blumberg positivo. ¿Cuál es la conducta?",o:["Antibiótico oral y control en 48 h","Apendicectomía (previa imagen si hay duda)","Analgésicos y observación en casa","Colonoscopia"],a:1,e:"Cuadro clásico de apendicitis aguda (escala de Alvarado alta): manejo quirúrgico con antibiótico profiláctico. La ecografía o TAC se usan ante duda diagnóstica (mujer en edad fértil, obeso). La analgesia no debe retrasarse ni 'enmascara' el diagnóstico.",p:"Apendicitis es la causa más frecuente de abdomen agudo quirúrgico; en embarazada el dolor puede estar más alto."},
{id:"q02",area:"Cirugía",tema:"Vía biliar",dif:2,q:"Mujer de 60 años con fiebre, ictericia y dolor en hipocondrio derecho (tríada de Charcot), confusión e hipotensión. ¿Cuál es el manejo?",o:["Colecistectomía laparoscópica urgente","Antibiótico IV + descompresión biliar urgente (CPRE)","Ácido ursodesoxicólico","Solo antibiótico y observación"],a:1,e:"Pentada de Reynolds (Charcot + confusión + hipotensión) indica colangitis aguda grave: reanimación, antibiótico de amplio espectro y drenaje biliar urgente, idealmente por CPRE. La colecistectomía se difiere.",p:"Charcot = colangitis; Reynolds = colangitis grave; Murphy = colecistitis."},
{id:"q03",area:"Cirugía",tema:"Hernias",dif:1,q:"Hombre de 55 años con masa inguinal dolorosa, irreductible, con náuseas, vómito y eritema sobre la piel. ¿Cuál es la conducta?",o:["Reducción manual forzada y alta","Cirugía urgente por hernia estrangulada","Faja y control en consulta","Antibiótico y analgesia"],a:1,e:"Hernia irreductible con dolor, signos de obstrucción y cambios cutáneos indica estrangulación: cirugía de urgencia. Nunca se intenta reducir una hernia con sospecha de estrangulación (riesgo de reintroducir asa necrótica).",p:"Hernia incarcerada: irreductible sin compromiso vascular; estrangulada: compromiso vascular (dolor intenso, toxicidad)."},
{id:"q04",area:"Cirugía",tema:"Trauma",dif:2,q:"Paciente con herida por arma cortopunzante en abdomen, hipotenso (PA 70/40) y abdomen distendido pese a 2 L de cristaloides. ¿Cuál es la conducta?",o:["TAC de abdomen con contraste","Laparotomía exploratoria inmediata","FAST y observación","Lavado peritoneal diagnóstico"],a:1,e:"Trauma abdominal penetrante con inestabilidad hemodinámica es indicación absoluta de laparotomía inmediata; la TAC solo se hace en pacientes estables. Otras indicaciones: evisceración, peritonitis, sangrado por recto o sonda nasogástrica.",p:"Inestable + trauma penetrante = quirófano; estable = TAC."},
{id:"q05",area:"Cirugía",tema:"Obstrucción intestinal",dif:2,q:"Mujer de 65 años con cirugía abdominal previa, dolor cólico, distensión, vómito y ausencia de deposiciones; radiografía con niveles hidroaéreos en intestino delgado. ¿Cuál es la causa más probable?",o:["Vólvulo de sigmoides","Bridas (adherencias) postoperatorias","Cáncer de colon","Hernia interna"],a:1,e:"La causa más frecuente de obstrucción de intestino delgado en pacientes con cirugía previa son las adherencias. El manejo inicial es conservador (sonda nasogástrica, líquidos, reposo intestinal) si no hay signos de estrangulación; el cáncer de colon es la causa más frecuente de obstrucción de colon.",p:"Signos de estrangulación: fiebre, taquicardia persistente, leucocitosis, acidosis, dolor continuo."},
{id:"q06",area:"Cirugía",tema:"Pie diabético",dif:2,q:"Diabético con úlcera plantar profunda que llega a hueso con prueba de sonda positiva, secreción purulenta y radiografía normal. ¿Cuál es la conducta?",o:["Curaciones y antibiótico tópico","Sospechar osteomielitis: RM o biopsia ósea y antibiótico prolongado ± desbridamiento","Amputación inmediata","Solo control glucémico"],a:1,e:"La prueba de sonda a hueso positiva tiene alto valor predictivo de osteomielitis; la radiografía puede ser normal las primeras 2-3 semanas. Se confirma con RM o biopsia ósea con cultivo y se trata con antibiótico prolongado (6 semanas) y desbridamiento según extensión.",p:"Evalúe siempre el componente vascular (pulsos, índice tobillo-brazo): sin flujo no hay cicatrización."},
{id:"q07",area:"Cirugía",tema:"Cáncer de mama",dif:2,q:"Mujer de 52 años con masa palpable de 2 cm en mama, dura, irregular, adherida. ¿Cuál es el estudio inicial más apropiado?",o:["Ecografía únicamente","Mamografía diagnóstica + ecografía y biopsia con aguja gruesa (trucut)","PET-TC","Biopsia excisional"],a:1,e:"Masa sospechosa en mujer >40 años: triple evaluación (clínica, imagen con mamografía ± ecografía, y biopsia con aguja gruesa que permite histología y receptores). La biopsia excisional no es el método inicial.",p:"BI-RADS 4 y 5 requieren biopsia; en <30 años inicie con ecografía por densidad mamaria."},
{id:"q08",area:"Cirugía",tema:"Preoperatorio",dif:2,q:"Paciente anticoagulado con warfarina por fibrilación auricular (CHA2DS2-VASc 3) programado para colecistectomía electiva. ¿Cuál es el manejo perioperatorio?",o:["Continuar warfarina sin cambios","Suspender warfarina 5 días antes sin puente con heparina","Suspender y hacer puente con heparina de bajo peso molecular","Suspender y dar vitamina K el mismo día"],a:1,e:"Para FA con riesgo tromboembólico bajo-moderado (sin válvula mecánica ni ictus reciente) la evidencia (BRIDGE) muestra que el puente con heparina aumenta sangrado sin reducir eventos. Se suspende warfarina 5 días antes y se verifica INR <1.5. El puente se reserva para válvula mecánica mitral, ictus/AIT reciente o TEV reciente.",p:"ACOD: suspender 1-2 días antes según función renal y riesgo de sangrado; no requieren puente."},
// ================= PEDIATRÍA =================
{id:"p01",area:"Pediatría",tema:"Deshidratación",dif:1,q:"Lactante de 10 meses con diarrea aguda, ojos hundidos, bebe ávidamente y signo del pliegue de 2 segundos, sin letargia. ¿Cuál es el plan de manejo?",o:["Plan A: sales de rehidratación en casa","Plan B: rehidratación oral supervisada 50-100 mL/kg en 4 h","Plan C: líquidos IV","Antibiótico y antidiarreico"],a:1,e:"Dos o más signos de deshidratación moderada (ojos hundidos, bebe ávidamente, pliegue lento) = 'algún grado de deshidratación' → plan B con SRO de baja osmolaridad en servicio de salud. Plan C solo con deshidratación grave (letargia, no puede beber, pliegue >2 s). Añadir zinc por 10-14 días.",p:"Antidiarreicos y antieméticos de rutina no están indicados; el zinc sí."},
{id:"p02",area:"Pediatría",tema:"Bronquiolitis",dif:1,q:"Lactante de 4 meses con rinorrea, tos, sibilancias difusas y tiraje leve, saturación 95 %, come bien. ¿Cuál es el manejo?",o:["Salbutamol + corticoide oral","Medidas de soporte: lavados nasales, hidratación y vigilancia","Antibiótico","Adrenalina nebulizada y hospitalizar"],a:1,e:"Bronquiolitis leve: tratamiento de soporte. Broncodilatadores, corticoides y antibióticos no han demostrado beneficio. Hospitalizar si saturación <92 %, dificultad para alimentarse, apneas o <2 meses con factores de riesgo.",p:"Bronquiolitis = primer episodio sibilante en <2 años con pródromo viral; la causa principal es el VSR."},
{id:"p03",area:"Pediatría",tema:"Neonatología",dif:2,q:"Recién nacido a término de 3 días con ictericia hasta el abdomen, bilirrubina total 14 mg/dL de predominio indirecto, alimentado con lactancia materna, Coombs negativo. ¿Cuál es la conducta?",o:["Suspender lactancia materna","Fototerapia según nomograma y continuar lactancia frecuente","Exanguinotransfusión","Fenobarbital"],a:1,e:"Ictericia fisiológica/asociada a lactancia en RN a término: decisión de fototerapia según nomograma de Bhutani por edad en horas y factores de riesgo; se mantiene la lactancia materna frecuente. La exanguinotransfusión es para valores muy altos o signos de encefalopatía.",p:"Ictericia en las primeras 24 h de vida SIEMPRE es patológica (hemólisis)."},
{id:"p04",area:"Pediatría",tema:"Crecimiento",dif:1,q:"Niño de 18 meses con peso/talla por debajo de −3 DE, edema bilateral de pies y dermatosis descamativa. ¿Cuál es el diagnóstico?",o:["Marasmo","Kwashiorkor (desnutrición aguda severa edematosa)","Síndrome nefrótico","Celiaquía"],a:1,e:"Edema bilateral en un niño con desnutrición define desnutrición aguda severa edematosa (kwashiorkor). Manejo hospitalario: fase de estabilización (hipoglucemia, hipotermia, infecciones, electrolitos; fórmula F-75) antes de la fase de recuperación (F-100/RUTF). No dar hierro en la fase inicial.",p:"Perímetro braquial <11.5 cm o edema bilateral = desnutrición aguda severa en 6-59 meses."},
{id:"p05",area:"Pediatría",tema:"Infecciones",dif:2,q:"Niño de 3 años con fiebre de 6 días, conjuntivitis bilateral no exudativa, labios fisurados, exantema, edema de manos y adenopatía cervical. ¿Cuál es el tratamiento?",o:["Antibiótico IV","Inmunoglobulina IV + aspirina","Corticoides","Paracetamol y observación"],a:1,e:"Enfermedad de Kawasaki (fiebre ≥5 días + 4 de 5 criterios): inmunoglobulina IV 2 g/kg en las primeras 10 días más aspirina para prevenir aneurismas coronarios. Es la principal causa de cardiopatía adquirida en niños. Requiere ecocardiograma.",p:"Fiebre + descamación periungueal tardía + trombocitosis = Kawasaki."},
{id:"p06",area:"Pediatría",tema:"Vacunación",dif:2,q:"Según el esquema PAI de Colombia, ¿qué vacunas se aplican a los 2 meses de edad?",o:["BCG y hepatitis B","Pentavalente, polio, rotavirus y neumococo","Triple viral y varicela","Fiebre amarilla y hepatitis A"],a:1,e:"A los 2 meses: pentavalente (DPT + Hib + hepatitis B), polio (IPV), rotavirus y neumococo conjugado. BCG y hepatitis B son al nacer; triple viral (SRP), varicela y hepatitis A a los 12 meses; fiebre amarilla a los 18 meses.",p:"Al nacer: BCG + hepatitis B. 12 meses: SRP, varicela, hepatitis A, neumococo refuerzo. 18 meses: fiebre amarilla, refuerzos."},
{id:"p07",area:"Pediatría",tema:"Convulsión febril",dif:1,q:"Niño de 2 años con convulsión tónico-clónica generalizada de 3 minutos durante fiebre de 39 °C, sin focalización y examen neurológico normal tras el evento. ¿Cuál es la conducta?",o:["Punción lumbar y EEG","Tranquilizar a los padres, control de la fiebre y buscar foco infeccioso","Iniciar ácido valproico profiláctico","TAC de cráneo urgente"],a:1,e:"Convulsión febril simple (generalizada, <15 min, única en 24 h, entre 6 meses y 5 años): no requiere EEG, neuroimagen ni profilaxis anticonvulsivante. La punción lumbar se considera en <12 meses sin vacunación completa o con signos meníngeos.",p:"Convulsión febril compleja: focal, >15 min o recurrente en 24 h → requiere estudio."},
// ================= GINECO-OBSTETRICIA =================
{id:"o01",area:"Ginecoobstetricia",tema:"Preeclampsia",dif:2,q:"Gestante de 34 semanas con PA 165/112, cefalea, proteinuria y plaquetas 90.000. ¿Cuál es el manejo inicial?",o:["Observación ambulatoria","Antihipertensivo IV (labetalol/nifedipino) + sulfato de magnesio y programar parto","Diuréticos y reposo","Aspirina"],a:1,e:"Preeclampsia con criterios de severidad: controlar la PA (labetalol IV, nifedipino oral o hidralazina), sulfato de magnesio para prevenir eclampsia, y terminar el embarazo (después de maduración pulmonar si <34 semanas y hay estabilidad). El tratamiento definitivo es el parto.",p:"Signos de toxicidad por magnesio: pérdida de reflejos patelares, FR <12; antídoto gluconato de calcio."},
{id:"o02",area:"Ginecoobstetricia",tema:"Hemorragia obstétrica",dif:2,q:"Puérpera inmediata con sangrado abundante tras parto vaginal, útero blando y por encima del ombligo. ¿Cuál es la causa y la primera medida?",o:["Retención de placenta; legrado","Atonía uterina; masaje uterino y oxitocina","Desgarro vaginal; sutura","Coagulopatía; plasma"],a:1,e:"Atonía uterina (70 % de las hemorragias posparto): masaje bimanual y uterotónicos (oxitocina de primera línea; luego misoprostol, metilergonovina si no hay HTA, carbetocina) y ácido tranexámico. Las 4 T: tono, tejido, trauma, trombina.",p:"Manejo activo del tercer periodo (oxitocina profiláctica) reduce la hemorragia posparto."},
{id:"o03",area:"Ginecoobstetricia",tema:"Embarazo ectópico",dif:2,q:"Mujer con amenorrea de 7 semanas, dolor pélvico, β-hCG 2.500 mUI/mL y ecografía transvaginal sin saco intrauterino, con masa anexial de 2.5 cm, estable. ¿Cuál es la conducta?",o:["Repetir β-hCG en 1 semana","Metotrexato (tratamiento médico de ectópico no roto)","Laparotomía urgente","Legrado"],a:1,e:"β-hCG por encima de la zona discriminatoria (~1.500-2.000) sin saco intrauterino + masa anexial = embarazo ectópico. Estable, sin rotura, masa <3.5 cm y sin actividad cardíaca: metotrexato. Inestabilidad o rotura: cirugía (laparoscopia preferida).",p:"Contraindicaciones de metotrexato: inestabilidad, rotura, β-hCG >5.000, actividad cardíaca embrionaria, lactancia."},
{id:"o04",area:"Ginecoobstetricia",tema:"Tamización cervical",dif:1,q:"Mujer de 35 años. Según la guía colombiana, ¿cuál es la prueba de tamización primaria de cáncer de cuello uterino?",o:["Citología cada año","Prueba de ADN-VPH cada 5 años si es negativa","Colposcopia anual","Inspección visual con ácido acético"],a:1,e:"En Colombia, entre 30 y 65 años la tamización primaria es la prueba de ADN de VPH de alto riesgo; si es negativa se repite cada 5 años; si es positiva se realiza citología (triage). Entre 25-29 años se usa citología cada 3 años. La inspección visual es para zonas de difícil acceso.",p:"Vacuna VPH en el PAI: niñas y niños de 9 a 17 años, dosis única."},
{id:"o05",area:"Ginecoobstetricia",tema:"Diabetes gestacional",dif:2,q:"Gestante de 26 semanas con prueba de tolerancia a 75 g: glucosa en ayunas 95, 1 h 185, 2 h 150 mg/dL. ¿Cuál es la interpretación y el manejo inicial?",o:["Normal","Diabetes gestacional; dieta, ejercicio y automonitoreo; insulina si no se controla","Diabetes pregestacional; metformina","Repetir la prueba en 4 semanas"],a:1,e:"Con un solo valor alterado (ayunas ≥92, 1 h ≥180, 2 h ≥153) se diagnostica diabetes gestacional. El manejo inicial es nutricional y de ejercicio; si no se alcanzan metas (ayunas <95, posprandial 1 h <140), insulina es el fármaco de elección.",p:"Tamización universal entre semanas 24 y 28; en alto riesgo, desde la primera consulta."},
{id:"o06",area:"Ginecoobstetricia",tema:"Anticoncepción",dif:2,q:"Mujer de 36 años, fumadora de 20 cigarrillos/día, con migraña con aura, solicita anticoncepción. ¿Cuál es el método contraindicado?",o:["DIU de cobre","Anticonceptivos orales combinados","Implante subdérmico","DIU de levonorgestrel"],a:1,e:"Los anticonceptivos combinados (estrógeno) están contraindicados (categoría 4 OMS) en migraña con aura (riesgo de ACV) y en fumadoras ≥35 años de ≥15 cigarrillos. Los métodos de solo progestina y los DIU son seguros.",p:"Otras contraindicaciones absolutas de estrógenos: TEV previo, HTA no controlada, cáncer de mama actual, lactancia <6 semanas."},
{id:"o07",area:"Ginecoobstetricia",tema:"Parto pretérmino",dif:2,q:"Gestante de 30 semanas con contracciones regulares y cuello dilatado 3 cm. ¿Cuál de las siguientes intervenciones mejora el pronóstico neonatal?",o:["Reposo absoluto","Corticoides antenatales (betametasona) + sulfato de magnesio para neuroprotección","Antibiótico profiláctico sin más","Progesterona vaginal"],a:1,e:"En amenaza de parto pretérmino entre 24 y 34 semanas: corticoides antenatales reducen síndrome de dificultad respiratoria, hemorragia intraventricular y mortalidad; sulfato de magnesio antes de las 32 semanas reduce parálisis cerebral. La tocólisis solo gana tiempo (48 h) para los corticoides.",p:"Betametasona 12 mg IM cada 24 h x 2 dosis; el beneficio máximo es entre 24 h y 7 días después."},
// ================= SALUD PÚBLICA / EPIDEMIOLOGÍA =================
{id:"s01",area:"Salud pública y epidemiología",tema:"Pruebas diagnósticas",dif:2,q:"Una prueba tiene sensibilidad 90 % y especificidad 80 %. Si se aplica en una población con prevalencia 10 %, ¿cuál es aproximadamente el valor predictivo positivo?",o:["90 %","33 %","80 %","50 %"],a:1,e:"En 1.000 personas: 100 enfermos → 90 verdaderos positivos; 900 sanos → 180 falsos positivos. VPP = 90/(90+180) = 33 %. El VPP depende de la prevalencia; con prevalencia baja, incluso pruebas buenas dan muchos falsos positivos.",p:"SnNout: sensibilidad alta, negativo descarta. SpPin: especificidad alta, positivo confirma."},
{id:"s02",area:"Salud pública y epidemiología",tema:"Diseños de estudio",dif:2,q:"Un investigador compara pacientes con cáncer de pulmón y controles sanos preguntando sobre exposición previa a asbesto. ¿Qué tipo de estudio y qué medida de asociación corresponde?",o:["Cohorte; riesgo relativo","Casos y controles; odds ratio","Transversal; prevalencia","Ensayo clínico; reducción absoluta del riesgo"],a:1,e:"Parte del desenlace hacia la exposición = estudio de casos y controles; la medida es la razón de odds (OR). Es eficiente para enfermedades raras pero sujeto a sesgo de memoria. En cohortes se parte de la exposición y se calcula RR.",p:"OR ≈ RR cuando la enfermedad es rara (<10 %)."},
{id:"s03",area:"Salud pública y epidemiología",tema:"Bioestadística",dif:2,q:"En un ensayo clínico, la mortalidad fue 10 % con el tratamiento y 15 % con placebo. ¿Cuál es el número necesario a tratar (NNT)?",o:["5","20","10","50"],a:1,e:"Reducción absoluta del riesgo = 15 % − 10 % = 5 % = 0.05. NNT = 1/RAR = 1/0.05 = 20. La reducción relativa del riesgo sería 33 %, pero el NNT se calcula con la absoluta.",p:"NNT = 1 / reducción absoluta del riesgo; el RRR exagera el beneficio cuando el riesgo basal es bajo."},
{id:"s04",area:"Salud pública y epidemiología",tema:"Vigilancia",dif:1,q:"En Colombia, ¿cuál de los siguientes eventos es de notificación obligatoria inmediata al SIVIGILA?",o:["Hipertensión arterial","Sarampión (caso sospechoso)","Diabetes mellitus","Lumbalgia mecánica"],a:1,e:"El sarampión es un evento de notificación inmediata (en las primeras 24 h) por su potencial epidémico y las metas de eliminación. Las enfermedades crónicas no transmisibles no se notifican individualmente al SIVIGILA de forma inmediata.",p:"Notificación inmediata: sarampión, rubéola, parálisis flácida aguda, fiebre amarilla, cólera, rabia, muerte materna, ESAVI grave."},
{id:"s05",area:"Salud pública y epidemiología",tema:"Sistema de salud",dif:1,q:"En el Sistema General de Seguridad Social en Salud de Colombia (Ley 100 de 1993), ¿cuál entidad es responsable de la afiliación y garantizar la prestación del plan de beneficios?",o:["IPS","EPS","ADRES","Superintendencia de Salud"],a:1,e:"Las EPS (Entidades Promotoras de Salud) afilian, administran el riesgo y garantizan la prestación de los servicios del plan de beneficios a través de IPS (prestadores). La ADRES administra los recursos (antes FOSYGA) y la Supersalud vigila.",p:"Ley 1751 de 2015 (estatutaria): la salud como derecho fundamental. Resolución 3100 de 2019: habilitación de servicios."},
{id:"s06",area:"Salud pública y epidemiología",tema:"Bioestadística",dif:2,q:"Un estudio reporta un riesgo relativo de 0.8 con IC 95 % de 0.6 a 1.1. ¿Cuál es la interpretación correcta?",o:["El tratamiento reduce el riesgo significativamente","La diferencia no es estadísticamente significativa porque el intervalo incluye 1","El tratamiento aumenta el riesgo","El valor p es menor de 0.05"],a:1,e:"Para medidas de razón (RR, OR, HR) el valor nulo es 1; si el intervalo de confianza del 95 % lo incluye, el resultado no es estadísticamente significativo (p >0.05), aunque la estimación puntual sugiera reducción.",p:"Para diferencias (RAR, diferencia de medias) el valor nulo es 0; para razones es 1."},
{id:"s07",area:"Salud pública y epidemiología",tema:"Sesgos",dif:3,q:"Un programa de tamización detecta cánceres en etapas más tempranas y los pacientes 'viven más' desde el diagnóstico, pero la mortalidad total no cambia. ¿Qué sesgo explica esto?",o:["Sesgo de selección","Sesgo de adelanto diagnóstico (lead-time)","Sesgo de memoria","Confusión"],a:1,e:"El sesgo de adelanto diagnóstico ocurre cuando la detección temprana aumenta el tiempo de supervivencia aparente sin retrasar la muerte. Por eso la eficacia de un tamizaje se evalúa con mortalidad, no con supervivencia desde el diagnóstico.",p:"Sesgo de duración (length-time): la tamización detecta preferentemente tumores de crecimiento lento y mejor pronóstico."},
// ================= ÉTICA / PROFESIONALISMO =================
{id:"t01",area:"Ética y profesionalismo",tema:"Consentimiento",dif:1,q:"Paciente adulto, lúcido y competente, rechaza una transfusión que puede salvarle la vida por motivos religiosos. ¿Cuál es la conducta ética y legal en Colombia?",o:["Transfundir contra su voluntad porque está en riesgo vital","Respetar su decisión, documentarla y ofrecer alternativas","Solicitar orden judicial de urgencia","Sedarlo y transfundir"],a:1,e:"El principio de autonomía y la jurisprudencia de la Corte Constitucional colombiana protegen el derecho de un adulto competente a rechazar tratamientos, incluso vitales, siempre que la decisión sea informada y libre. Se documenta el consentimiento informado de rechazo y se ofrecen alternativas.",p:"En menores de edad, el interés superior del niño prevalece y puede requerirse intervención judicial."},
{id:"t02",area:"Ética y profesionalismo",tema:"Confidencialidad",dif:2,q:"Un paciente con VIH le pide que no informe a su pareja, con quien tiene relaciones sin protección. ¿Cuál es la conducta más adecuada?",o:["Mantener el secreto absoluto","Aconsejar y acompañar al paciente para que revele; si se niega, informar a la pareja en riesgo como excepción justificada al secreto","Informar inmediatamente a la pareja sin hablar con el paciente","Negarse a seguir atendiendo al paciente"],a:1,e:"El secreto profesional (Ley 23 de 1981) tiene excepciones cuando hay riesgo grave para terceros. La conducta es primero persuadir y apoyar al paciente para que informe; si persiste la negativa, el médico puede revelar la información mínima necesaria a la persona en riesgo.",p:"Ley 23 de 1981 (ética médica): el secreto se levanta por mandato legal, por riesgo a terceros o con autorización del paciente."},
{id:"t03",area:"Ética y profesionalismo",tema:"Final de vida",dif:2,q:"Paciente con cáncer terminal y dolor refractario solicita sedación paliativa. ¿Cuál es la diferencia fundamental respecto a la eutanasia?",o:["No hay diferencia","La sedación paliativa busca aliviar el sufrimiento refractario sin buscar la muerte; la eutanasia busca directamente la muerte a petición del paciente","La sedación paliativa es ilegal en Colombia","La eutanasia solo requiere consentimiento de la familia"],a:1,e:"La sedación paliativa reduce la conciencia para aliviar síntomas refractarios y es parte del cuidado paliativo estándar. La eutanasia (despenalizada en Colombia por la Corte Constitucional, reglamentada por el Ministerio de Salud) implica causar la muerte a petición expresa de un paciente con sufrimiento intolerable.",p:"Colombia: eutanasia despenalizada desde la sentencia C-239 de 1997; ampliada a enfermedades no terminales por C-233 de 2021."},
// ================= CIENCIAS BÁSICAS / FARMACOLOGÍA =================
{id:"b01",area:"Ciencias básicas y farmacología",tema:"Farmacología",dif:2,q:"Paciente que inicia enalapril presenta tos seca persistente. ¿Cuál es el mecanismo y la alternativa?",o:["Alergia; suspender todo antihipertensivo","Acumulación de bradicinina; cambiar a un ARA II (losartán)","Broncoespasmo; agregar salbutamol","Reflujo; agregar omeprazol"],a:1,e:"Los IECA inhiben la degradación de bradicinina, causando tos seca en 10-20 % de pacientes y, raramente, angioedema. Los ARA II bloquean el receptor AT1 sin afectar la bradicinina. Ambos están contraindicados en embarazo.",p:"Angioedema por IECA contraindica también los ARA II en la mayoría de guías."},
{id:"b02",area:"Ciencias básicas y farmacología",tema:"Fisiología",dif:2,q:"¿Cuál es el principal estímulo para la secreción de hormona antidiurética (ADH) en condiciones fisiológicas?",o:["Disminución del potasio sérico","Aumento de la osmolaridad plasmática","Aumento de la presión arterial","Hipoglucemia"],a:1,e:"Los osmorreceptores hipotalámicos detectan aumentos de 1-2 % en la osmolaridad y estimulan ADH. La hipovolemia severa (caída >10 % del volumen) es un estímulo no osmótico más potente pero menos sensible.",p:"SIADH: hiponatremia hipoosmolar euvolémica con orina inapropiadamente concentrada (>100 mOsm/kg)."},
{id:"b03",area:"Ciencias básicas y farmacología",tema:"Farmacología",dif:2,q:"Paciente en tratamiento con warfarina inicia tratamiento con rifampicina por tuberculosis. ¿Qué efecto se espera?",o:["Aumento del INR y riesgo de sangrado","Disminución del INR por inducción enzimática","Sin interacción","Hemólisis"],a:1,e:"La rifampicina es un potente inductor del citocromo P450 (CYP2C9, 3A4), acelerando el metabolismo de warfarina y reduciendo el INR; se requiere aumentar la dosis y monitorizar. Inhibidores (amiodarona, fluconazol, metronidazol, TMP-SMX) aumentan el INR.",p:"Inductores: rifampicina, fenitoína, carbamazepina, fenobarbital, hierba de San Juan. Inhibidores: azoles, macrólidos, amiodarona, jugo de toronja."},
{id:"b04",area:"Ciencias básicas y farmacología",tema:"Inmunología",dif:2,q:"Paciente desarrolla nefritis intersticial, fiebre, eosinofilia y exantema 10 días después de iniciar un betalactámico. ¿Qué tipo de reacción de hipersensibilidad es?",o:["Tipo I (IgE)","Tipo IV (mediada por células T)","Tipo II (citotóxica)","Tipo III (inmunocomplejos)"],a:1,e:"La nefritis intersticial aguda por fármacos es una reacción de hipersensibilidad retardada tipo IV (linfocitos T), con la tríada fiebre, exantema y eosinofilia (presente en <30 %). Tratamiento: suspender el fármaco ± corticoides. La tipo I es inmediata (anafilaxia).",p:"Tipo I: anafilaxia. Tipo II: anemia hemolítica por fármacos, Goodpasture. Tipo III: enfermedad del suero, lupus. Tipo IV: dermatitis de contacto, tuberculina."},
{id:"b05",area:"Ciencias básicas y farmacología",tema:"Farmacocinética",dif:2,q:"Un fármaco tiene vida media de 8 horas. Si se inicia infusión continua sin dosis de carga, ¿aproximadamente cuándo alcanza el estado estable?",o:["8 horas","32-40 horas (4-5 vidas medias)","24 horas","80 horas"],a:1,e:"El estado estable se alcanza tras 4-5 vidas medias (≈94-97 % de la concentración final), independientemente de la dosis. Por eso se usan dosis de carga para fármacos de vida media larga (amiodarona, digoxina) cuando se necesita efecto rápido.",p:"La dosis de carga depende del volumen de distribución; la de mantenimiento, del aclaramiento."},
{id:"b06",area:"Ciencias básicas y farmacología",tema:"Microbiología",dif:1,q:"¿Cuál es el mecanismo de acción de la vancomicina?",o:["Inhibe la síntesis proteica en la subunidad 30S","Inhibe la síntesis de pared celular uniéndose a D-Ala-D-Ala del peptidoglicano","Inhibe la ADN girasa","Inhibe la síntesis de folato"],a:1,e:"La vancomicina (glucopéptido) se une a los extremos D-alanil-D-alanina de los precursores del peptidoglicano, bloqueando la síntesis de pared en grampositivos. La resistencia (VRE) surge por cambio a D-Ala-D-Lac. Los aminoglucósidos actúan en 30S; las quinolonas en la girasa; TMP-SMX en folatos.",p:"Vancomicina: monitorice niveles valle (o AUC) y función renal; 'síndrome del hombre rojo' por infusión rápida no es alergia."},
{id:"b07",area:"Ciencias básicas y farmacología",tema:"Fisiología",dif:2,q:"En la curva de disociación de la hemoglobina, ¿cuál de los siguientes desplaza la curva hacia la derecha (menor afinidad por el O2)?",o:["Alcalosis","Hipotermia","Aumento de 2,3-DPG, acidosis e hipertermia","Disminución de PaCO2"],a:2,e:"Acidosis, hipercapnia, hipertermia y aumento de 2,3-difosfoglicerato desplazan la curva a la derecha, facilitando la liberación de O2 a los tejidos (efecto Bohr). Alcalosis, hipotermia, hipocapnia y hemoglobina fetal la desplazan a la izquierda.",p:"Derecha = 'entrega' (ejercicio, tejidos); izquierda = 'retiene' (pulmón, Hb fetal, CO)."},
// ================= MÁS MEDICINA INTERNA (ALTA FRECUENCIA) =================
{id:"m01",area:"Cardiología",tema:"Hipertensión",dif:1,q:"Hombre de 50 años con PA 150/95 confirmada en 3 visitas, sin daño de órgano blanco, riesgo cardiovascular moderado. ¿Cuál es la meta de presión arterial recomendada?",o:["<160/100","<130/80 si se tolera","<150/90","<120/70 en todos"],a:1,e:"Las guías actuales recomiendan una meta <130/80 mmHg en la mayoría de adultos con HTA si se tolera (al menos <140/90). Iniciar con cambios de estilo de vida y, en grado 1 con riesgo moderado, fármacos si no se controla en 3-6 meses; en general se prefiere combinación en una sola tableta.",p:"Fármacos de primera línea: IECA/ARA, calcioantagonista, diurético tiazídico. Betabloqueadores solo con indicación específica."},
{id:"m02",area:"Neumología",tema:"EPOC",dif:2,q:"Paciente con exacerbación de EPOC, pH 7.28, PaCO2 65, PaO2 55, alerta y colaborador. ¿Cuál es la intervención con mayor impacto en mortalidad?",o:["Oxígeno a alto flujo con máscara de no reinhalación","Ventilación mecánica no invasiva (BiPAP)","Aminofilina IV","Corticoide inhalado a dosis altas"],a:1,e:"Acidosis respiratoria aguda (pH <7.35 con PaCO2 >45) en exacerbación de EPOC es indicación de VMNI, que reduce intubación y mortalidad. El oxígeno se titula a saturación 88-92 % para evitar hipercapnia. También se dan broncodilatadores, corticoide sistémico 5 días y antibiótico si esputo purulento.",p:"Meta de saturación en EPOC exacerbado: 88-92 %."},
{id:"m03",area:"Infectología",tema:"VIH",dif:2,q:"Paciente con VIH recién diagnosticado, CD4 350, asintomático. ¿Cuándo iniciar terapia antirretroviral?",o:["Solo cuando CD4 <200","Lo antes posible, independientemente del CD4","Cuando aparezcan síntomas","Cuando la carga viral sea >100.000"],a:1,e:"Las guías actuales (OMS, Colombia) recomiendan iniciar TAR en todos los pacientes con VIH lo antes posible tras el diagnóstico, independientemente del CD4, para reducir mortalidad, transmisión y comorbilidades. Esquema preferido: tenofovir + lamivudina/emtricitabina + dolutegravir.",p:"Excepción al inicio inmediato: meningitis criptocócica y tuberculosa (retrasar 4-8 semanas)."},
{id:"m04",area:"Gastroenterología",tema:"Hemorragia digestiva",dif:2,q:"Hombre de 60 años con melenas, Hb 7 g/dL, FC 110, consumo de AINE. Tras reanimación, ¿cuál es el manejo farmacológico y el momento de la endoscopia?",o:["Octreótido y endoscopia en 72 h","Inhibidor de bomba de protones IV y endoscopia en las primeras 24 h","Vitamina K y colonoscopia","Antibiótico y TAC"],a:1,e:"Hemorragia digestiva alta no variceal (sospecha de úlcera por AINE): IBP IV y endoscopia en <24 h, con tratamiento endoscópico si hay estigmas de alto riesgo (Forrest Ia-IIb). Transfusión con umbral Hb <7 (8 en cardiópatas). Suspender AINE y erradicar H. pylori.",p:"Escala de Glasgow-Blatchford 0-1 permite manejo ambulatorio."},
{id:"m05",area:"Endocrinología",tema:"Diabetes tipo 2",dif:1,q:"¿Cuál de los siguientes criterios diagnostica diabetes mellitus?",o:["Glucosa en ayunas 115 mg/dL","HbA1c ≥6.5 %","Glucosa aleatoria 180 mg/dL sin síntomas","HbA1c 6.0 %"],a:1,e:"Criterios: glucosa en ayunas ≥126, HbA1c ≥6.5 %, glucosa a las 2 h de PTOG 75 g ≥200, o glucosa aleatoria ≥200 con síntomas clásicos. Requiere confirmación con una segunda prueba salvo hiperglucemia inequívoca. Ayunas 100-125 y HbA1c 5.7-6.4 % es prediabetes.",p:"HbA1c no es confiable en anemia, hemoglobinopatías, ERC avanzada o embarazo."},
{id:"m06",area:"Cardiología",tema:"Falla cardíaca",dif:2,q:"Paciente con falla cardíaca descompensada, disnea en reposo, crepitantes bilaterales, PA 150/90 y saturación 86 %. ¿Cuál es el manejo inicial?",o:["Betabloqueador IV","Diurético de asa IV + vasodilatador (nitroglicerina) + oxígeno/VMNI","Bolo de líquidos","Digoxina"],a:1,e:"Edema pulmonar agudo 'caliente y húmedo' (congestión con buena perfusión): diurético de asa IV, nitroglicerina si la PA lo permite y soporte ventilatorio (VMNI). Los betabloqueadores no se inician en descompensación aguda, aunque se mantienen si ya los tomaba y no hay choque.",p:"Perfiles de Stevenson: caliente-húmedo (diurético + vasodilatador), frío-húmedo (inotrópico), frío-seco (líquidos cautos)."},
{id:"m07",area:"Nefrología",tema:"Hipokalemia",dif:2,q:"Paciente con K 2.4 mEq/L, debilidad muscular y extrasístoles ventriculares. ¿Cuál es la reposición apropiada?",o:["Cloruro de potasio IV a 40 mEq/h por vena periférica","Cloruro de potasio IV máximo 10-20 mEq/h con monitoreo ECG y corrección de magnesio","Potasio oral únicamente","Bicarbonato IV"],a:1,e:"Hipokalemia severa sintomática: KCl IV a 10 mEq/h por vía periférica (hasta 20 mEq/h por central con monitoreo), diluido, nunca en bolo. Siempre medir y corregir el magnesio, pues la hipomagnesemia perpetúa la hipokalemia.",p:"Sin corregir magnesio, el potasio 'no sube'."},
{id:"m08",area:"Infectología",tema:"Neumonía",dif:2,q:"Paciente hospitalizado hace 7 días en UCI, intubado, desarrolla fiebre, secreciones purulentas e infiltrado nuevo. ¿Cuál es el tratamiento empírico más apropiado?",o:["Amoxicilina-clavulanato oral","Cobertura antipseudomonas (piperacilina-tazobactam o cefepime) ± vancomicina según riesgo de SARM","Azitromicina sola","Ceftriaxona sola"],a:1,e:"Neumonía asociada al ventilador tardía (>5 días) implica riesgo de gérmenes multirresistentes: cubrir Pseudomonas (y SARM si hay factores de riesgo o alta prevalencia local), ajustando según cultivo de secreción traqueal.",p:"Prevención de NAV: cabecera a 30-45°, higiene oral con clorhexidina, interrupción diaria de sedación, evaluar extubación temprana."},
{id:"m09",area:"Hematología",tema:"Trombosis",dif:2,q:"Mujer de 45 años con trombosis venosa profunda proximal no provocada, sin cáncer ni insuficiencia renal. ¿Cuál es el tratamiento y la duración mínima?",o:["Aspirina 3 meses","Anticoagulante oral directo (rivaroxabán/apixabán) por al menos 3 meses y considerar extenderlo","Heparina IV 5 días y suspender","Medias de compresión únicamente"],a:1,e:"TVP: anticoagulación mínima de 3 meses; en TEV no provocado se recomienda considerar anticoagulación extendida si el riesgo de sangrado es bajo. Los ACOD son primera línea salvo cáncer gastrointestinal (HBPM) o síndrome antifosfolípido (warfarina).",p:"Síndrome antifosfolípido: warfarina, no ACOD."},
{id:"m10",area:"Neurología",tema:"ACV",dif:2,q:"Paciente con fibrilación auricular y episodio de disartria y debilidad del brazo derecho que resolvió en 30 minutos. RM sin infarto. ¿Cuál es la conducta para prevención secundaria?",o:["Aspirina + clopidogrel permanente","Anticoagulación oral (ACOD) tras descartar hemorragia","Estatina únicamente","Ninguna, fue transitorio"],a:1,e:"AIT cardioembólico por FA: la prevención secundaria es anticoagulación oral (ACOD preferido), que es superior a la antiagregación. Para AIT no cardioembólico se usa doble antiagregación por 21 días y luego monoterapia.",p:"Escala ABCD2 estratifica riesgo de ictus tras AIT, pero todo AIT se estudia con urgencia (imagen, vasos, ECG)."},
{id:"m11",area:"Endocrinología",tema:"Tiroides",dif:2,q:"Mujer de 50 años con nódulo tiroideo de 2 cm, TSH normal, ecografía con microcalcificaciones, hipoecogenicidad y bordes irregulares. ¿Cuál es el siguiente paso?",o:["Gammagrafía tiroidea","Biopsia por aspiración con aguja fina guiada por ecografía","Levotiroxina supresiva","Tiroidectomía total directa"],a:1,e:"Nódulo con características ecográficas de alto riesgo (TI-RADS 5) ≥1 cm: BACAF guiada por ecografía, clasificada por Bethesda. La gammagrafía solo se indica si la TSH está suprimida (nódulo caliente, raramente maligno).",p:"TSH baja → gammagrafía; TSH normal/alta → ecografía y BACAF según TI-RADS y tamaño."},
{id:"m12",area:"Reumatología",tema:"Espondiloartritis",dif:2,q:"Hombre de 25 años con lumbalgia de 6 meses que empeora en reposo y mejora con actividad, rigidez matutina >30 min, HLA-B27 positivo y sacroileítis en RM. ¿Cuál es el tratamiento de primera línea?",o:["Metotrexato","AINE a dosis plenas + ejercicio; anti-TNF si falla","Prednisona oral","Reposo en cama"],a:1,e:"Lumbalgia inflamatoria con sacroileítis = espondiloartritis axial (espondilitis anquilosante). Primera línea: AINE continuos y fisioterapia; si no responde a 2 AINE, biológicos anti-TNF o anti-IL-17. El metotrexato no es eficaz en enfermedad axial.",p:"Lumbalgia inflamatoria: inicio <40 años, insidiosa, mejora con ejercicio, no con reposo, dolor nocturno."},
{id:"m13",area:"Cardiología",tema:"Arritmias",dif:2,q:"Hombre de 75 años con bloqueo AV completo, FC 35, mareo e hipotensión. ¿Cuál es la conducta inicial y definitiva?",o:["Amiodarona; luego ablación","Atropina/marcapasos transcutáneo o dopamina como puente; marcapasos definitivo","Adenosina","Cardioversión"],a:1,e:"Bradicardia sintomática por bloqueo AV completo: atropina (poco eficaz en bloqueo infrahisiano), marcapasos transcutáneo o infusión de dopamina/adrenalina como puente, y marcapasos definitivo. Descartar causas reversibles (hiperkalemia, betabloqueadores, isquemia, Lyme, Chagas).",p:"En Colombia, en bloqueo AV en adulto joven de zona endémica piense en cardiopatía chagásica."},
{id:"m14",area:"Infectología",tema:"Fiebre tifoidea",dif:2,q:"Paciente con fiebre prolongada escalonada, cefalea, bradicardia relativa, dolor abdominal y roséola en tronco tras viaje con consumo de agua no tratada. ¿Cuál es la prueba diagnóstica de elección?",o:["Reacción de Widal","Hemocultivo","Coprocultivo únicamente","Gota gruesa"],a:1,e:"Fiebre tifoidea: el hemocultivo es la prueba de elección en la primera semana (sensibilidad 60-80 %); el mielocultivo es el más sensible. La reacción de Widal tiene baja especificidad. Tratamiento: ceftriaxona o azitromicina (alta resistencia a quinolonas).",p:"Fiebre + bradicardia relativa (signo de Faget): tifoidea, fiebre amarilla, dengue, brucelosis."},
{id:"m15",area:"Gastroenterología",tema:"Diarrea",dif:1,q:"Adulto con diarrea acuosa de 2 días sin sangre, sin fiebre, tras comer en la calle. Leve deshidratación. ¿Cuál es el manejo?",o:["Ciprofloxacina 5 días","Rehidratación oral; loperamida si no hay fiebre ni disentería","Metronidazol","Coprocultivo obligatorio antes de tratar"],a:1,e:"Diarrea aguda acuosa no inflamatoria es autolimitada (viral o toxigénica): hidratación oral y, en adultos sin fiebre ni sangre, loperamida sintomática. Antibióticos solo en disentería, fiebre alta, inmunosupresión o diarrea del viajero moderada-severa.",p:"Diarrea con sangre + fiebre = inflamatoria (Shigella, Campylobacter, E. coli enteroinvasiva): coprocultivo y evaluar antibiótico; evite loperamida."},
{id:"m16",area:"Neumología",tema:"Tromboembolismo",dif:2,q:"Mujer de 30 años con disnea súbita, FC 105, sin hemoptisis ni signos de TVP, sin cirugía reciente ni cáncer. Probabilidad clínica baja por Wells. ¿Cuál es el siguiente paso?",o:["AngioTAC pulmonar directamente","Dímero D; si negativo, se descarta TEP","Anticoagular empíricamente","Gammagrafía V/Q"],a:1,e:"Con probabilidad pretest baja o intermedia, un dímero D negativo (ajustado a edad >50: edad × 10 ng/mL) excluye TEP sin imagen. Con probabilidad alta se va directo a angioTAC. El dímero D no sirve para confirmar.",p:"Dímero D: alto valor predictivo negativo; en embarazo, posoperatorio o cáncer casi siempre está elevado."},
{id:"m17",area:"Cardiología",tema:"SCA",dif:2,q:"Paciente con dolor torácico típico, troponina elevada y ECG con descenso del ST en V4-V6, sin elevación. ¿Cuál es el diagnóstico y el manejo antitrombótico inicial?",o:["Angina estable; nitratos orales","IAM sin elevación del ST; aspirina + inhibidor P2Y12 + anticoagulación (enoxaparina/fondaparinux) y estratificar para coronariografía temprana","IAM con elevación del ST; trombólisis","Pericarditis; AINE"],a:1,e:"Troponina elevada con ECG sin elevación del ST = IAMSEST. Manejo: doble antiagregación (aspirina + ticagrelor/clopidogrel), anticoagulación parenteral, estatina de alta intensidad, betabloqueador si no hay contraindicación, y coronariografía en <24-72 h según riesgo (GRACE). La trombólisis NO está indicada en SCA sin elevación del ST.",p:"Trombólisis solo en IAMCEST; en IAMSEST está contraindicada."},
{id:"m18",area:"Nefrología",tema:"Hiponatremia",dif:2,q:"Paciente con hiponatremia (Na 125), hipovolemia por diarrea, Na urinario 10. ¿Cuál es el tratamiento?",o:["Restricción hídrica","Solución salina isotónica (0.9 %)","Solución salina al 3 % en bolo","Tolvaptán"],a:1,e:"Hiponatremia hipovolémica asintomática: reponer volumen con salina isotónica; al corregir la hipovolemia cesa el estímulo de ADH y el riñón excreta agua libre (vigile corrección rápida excesiva). La restricción hídrica es para SIADH; la hipertónica para síntomas graves.",p:"Clasifique siempre la hiponatremia por volemia: hipovolémica (salina), euvolémica/SIADH (restricción), hipervolémica (diurético + restricción)."},
{id:"m19",area:"Endocrinología",tema:"Suprarrenal",dif:3,q:"Paciente con HTA, obesidad central, estrías violáceas, hiperglucemia e hipokalemia. Cortisol urinario elevado y cortisol no suprime con 1 mg de dexametasona. ACTH elevada y RM de hipófisis con adenoma de 6 mm. ¿Cuál es el diagnóstico?",o:["Síndrome de Cushing por adenoma suprarrenal","Enfermedad de Cushing (adenoma hipofisario productor de ACTH)","Síndrome de Cushing ectópico","Cushing iatrogénico"],a:1,e:"Hipercortisolismo confirmado con ACTH elevada = dependiente de ACTH; la lesión hipofisaria orienta a enfermedad de Cushing (la causa más frecuente de Cushing endógeno). En adenoma suprarrenal la ACTH está suprimida. En ectópico suele haber hipokalemia marcada y ACTH muy alta, sin adenoma hipofisario (se confirma con cateterismo de senos petrosos si hay duda).",p:"Causa más frecuente de Cushing en general: iatrogénico (glucocorticoides exógenos)."},
{id:"m20",area:"Infectología",tema:"Chagas",dif:2,q:"Hombre de 45 años de zona rural de Santander con bloqueo de rama derecha, extrasístoles ventriculares y dilatación ventricular con aneurisma apical. ¿Cuál es la causa más probable?",o:["Miocardiopatía isquémica","Cardiopatía chagásica crónica","Miocarditis viral","Amiloidosis"],a:1,e:"Bloqueo de rama derecha + hemibloqueo anterior, arritmias ventriculares y aneurisma apical en paciente de zona endémica (Santander, Boyacá, Casanare) es característico de cardiopatía chagásica crónica. Se confirma con dos pruebas serológicas (ELISA + IFI).",p:"Chagas agudo: benznidazol/nifurtimox; en fase crónica cardíaca el beneficio del antiparasitario es limitado (BENEFIT)."},
];
